// 자동 생성: rules/*.md에서 npm run rules:sync로 만든다. 직접 수정 금지
export const RULES: Readonly<Record<string, string>> = JSON.parse(String.raw`{
  "00-common.md": "# 공통 규칙 (Paseo 연합개발 · 일반개발)\n\n> 에이전트 규칙 세트 v1.0 · 2026-10-31 · 모든 역할이 읽는다.\n\n## 0. 규칙 세트 구성\n\n| 파일                        | 내용                                                                               | 읽는 역할                    |\n| --------------------------- | ---------------------------------------------------------------------------------- | ---------------------------- |\n| \u0060README.md\u0060                 | 진입점, 상시 규칙 요약                                                             | 전원, 매 세션                |\n| \u0060project-settings.md\u0060       | 프로젝트 설정 기본값(프로젝트 AGENTS.md의 프로젝트 설정 절이 우선)                 | 전원                         |\n| \u006000-common.md\u0060              | 판단 우선순위, 용어, 운영 모드, 위험도, 증거 수준, 문서 지도, 작업 흐름, 세션 규칙 | 전원                         |\n| \u006010-planning.md\u0060            | 기획설계 역할                                                                      | 기획설계                     |\n| \u006020-implementation.md\u0060      | 구현 역할                                                                          | 구현                         |\n| \u006030-verification.md\u0060        | 검증 역할                                                                          | 검증                         |\n| \u006040-paseo-role-workflow.md\u0060 | Paseo role-workflow의 역할·상태 블록·안전장치·푸시와 규칙의 대응                   | 일반·연합개발의 plan·execute 대화 |\n\n- 규칙마다 원본은 이 세트 안에서 한 곳이다. **위험도(4절), 증거 수준(5절), 용어(2절), 운영 모드(3절), 문서 지도(6절)는 이 문서가 원본**이고, 역할 문서는 절 번호로 참조한다.\n- 역할 문서끼리, 또는 역할 문서와 이 문서가 충돌하면 진행하지 않고 사용자에게 보고한다. 에이전트가 우선순위를 임의로 정하지 않는다.\n- 규칙을 고칠 때는 원본 한 곳만 고치고 참조를 맞춘다. 모델별 복사본을 만들지 않는다.\n\n## 1. 판단 우선순위\n\n규칙이 충돌하면 위의 것이 이긴다. 상위 조건을 해치면서 하위 조건을 개선하지 않는다.\n\n1. 안전, 보안, 데이터 무결성, 법적·규제 요구, 반드시 보존할 외부 계약\n2. 기획설계가 확정하고 승인된 요구사항과 수락 기준\n3. 기존의 검증된 동작과 실험·수학적 의미\n4. 책임의 명확성, 구조의 일관성, 변경 범위\n5. 단순성, 성능, 개발·검증 비용\n\n이 순서로도 판단이 서지 않으면 멈추고 보고한다.\n\n## 2. 사실 표기와 용어\n\n### 2.1 사실 표기\n\n주요 진술에 아래 중 하나를 붙인다.\n\n| 표기       | 의미                                     | 함께 적을 것                        |\n| ---------- | ---------------------------------------- | ----------------------------------- |\n| \u0060[확인]\u0060   | 파일·실행 로그·시험·승인 기록으로 확인함 | 경로·위치·커밋, 환경·일시 또는 링크 |\n| \u0060[제안]\u0060   | 채택을 요청하는 구조·선택                | 대안, 이유, 영향, 승인 상태         |\n| \u0060[가정]\u0060   | 합리적이지만 확인하지 못함               | 틀렸을 때의 위험과 확인 방법        |\n| \u0060[미확정]\u0060 | 사용자 결정이나 추가 증거가 필요함       | 영향받는 작업과 착수 차단 여부      |\n\n하지 않은 실행은 \u0060[미실행]\u0060, 확인하지 못한 정보는 \u0060[미확인]\u0060으로 적는다. 승인된 명세는 목표의 기준이고, 코드·스키마·설정·실행 결과는 해당 커밋과 환경에서 관측된 동작의 근거다. 둘이 다르면 GAP으로 기록하며 어느 쪽도 자동으로 채택하지 않는다.\n\n### 2.2 용어\n\n- **REQ / NFR:** 기능 요구 / 비기능 요구. 프로젝트 전체에서 유일한 ID(\u0060REQ-0001\u0060).\n- **AC(수락 기준):** 요구 충족을 외부에서 관측할 수 있는 조건. \u0060REQ-0001.AC-01\u0060.\n- **수락 시험(TEST):** AC를 검증하는 시험 또는 수동 확인 절차. AC ID에 일련번호를 붙인다.\n- **ID 발급:** 발급 방식은 \u0060project-settings.md\u0060(프로젝트 AGENTS.md의 \"프로젝트 설정\" 절이 있으면 해당 절)에서 한 번만 정한다. 여러 에이전트가 동시에 발급할 수 있으면 작업 ID 접두어나 단일 예약 절차로 충돌을 막는다. 쓰지 않게 된 번호는 재사용하지 않는다.\n- **목표(Target):** 승인된, 앞으로 구현할 의도와 수락 기준.\n- **현재 적용 기준(Baseline):** 특정 릴리스·환경에 실제로 적용된 계약과 동작. 승인만 된 것은 Baseline이 아니다.\n- **변경 기록(Change record):** 무엇을 왜 바꿨는지의 증거(\u0060docs/changes/\u0060). 완료 뒤에도 보존하되 현행 계약을 재정의하지 않는다.\n- **GAP:** 승인된 목표와 확인한 현재 동작의 차이.\n- **계약:** API, 자료 형식·스키마, 설정 키, 출력의 의미, 오류·권한·외부 연동 약속.\n- **유지 / 통합 / 교체 / 제거:** 영향받는 기존 구현의 판정. 교체는 새 경로로 전환하면서 구 경로를 철거하는 것이다.\n- **동작 보존 리팩토링 / 의미 변경:** 외부 관측 동작을 보존하는 구조 변경 / 결과나 의미가 바뀌는 변경.\n- **덧대기:** 원래 책임 자리를 고치지 않고 옆이나 위에 같은 일을 하는 경로를 추가하는 것(20-implementation 6절이 판정 기준).\n- **증거:** 코드 위치, 시험·실행 로그, 스키마, 승인 이력처럼 다시 확인할 수 있는 자료.\n- **기준 커밋(base_commit):** 설계가 근거로 삼은 저장소 상태.\n- **기획설계 인계서 / 구현 인계 보고 / 검증 판정 보고:** 역할 사이에 넘기는 문서. 형식은 각각 10-planning 8절, 20-implementation 8절, 30-verification 7.2절.\n\n## 3. 운영 모드\n\nPaseo role-workflow는 대화를 시작할 때 **연합개발 / 일반개발**을 묻는다(기본값 연합개발). 규칙의 운영 모드는 이렇게 대응한다. 상태 블록·안전장치와의 대응은 \u006040-paseo-role-workflow.md\u0060.\n\n| 운영 모드 | role-workflow 구성                                                                                                                    | 쓰는 때                                   |\n| --------- | ------------------------------------------------------------------------------------------------------------------------------------- | ----------------------------------------- |\n| 교차 모델 | 연합개발. plan 대화(기본 Claude) = 기획설계 + 검증, execute 대화(기본 Codex) = 구현                                                   | 기본값                                    |\n| 단일 모델 | 연합개발이지만 plan과 execute를 같은 모델이 맡는다(예: Claude가 실행 담당)                                                            | 다른 모델을 쓸 수 없을 때                 |\n| 일반 개발 | 일반개발. 최초 대화가 기획설계·검증, 이후 선택한 별도 대화가 구현을 맡고 자동 인계한다(3.4) | 경미 작업, 또는 사용자가 지정한 일반 작업 |\n\n### 3.1 모든 모드 공통\n\n- 역할 경계는 모드와 상관없이 지킨다. 한 에이전트가 여러 역할을 맡아도 지금 어느 역할로 일하는지 밝히고 그 역할 문서를 따른다.\n- 역할 사이의 인계는 저장소 문서로 한다. 대화 요약이나 기억으로 인계하지 않는다.\n- 같은 모델의 자체 점검은 독립 검토가 아니다.\n- 고위험 작업은 구현에 참여하지 않은 다른 모델이 검증하기 전까지 최대 \"부분 완료\"다.\n\n### 3.2 교차 모델 (연합개발)\n\n- plan 대화는 10-planning과 30-verification을, execute 대화는 20-implementation을 따른다.\n- 인계는 상태 블록의 \u0060next\u0060·보고 본문에 인계 문서의 경로와 요약을 담아 한다(40-paseo-role-workflow 2절). 받는 쪽은 그 파일과 해당 역할 문서를 읽고 시작한다.\n- plan 대화가 자기 설계를 검토하게 되므로 30-verification 2절의 교차 모델 조건(다시 읽기, 설계 적합성 별도 판정, 고위험 추가 검토)을 지킨다.\n- 구현에 참여한 대화는 같은 작업의 검증자가 될 수 없다.\n- 같은 책임·계약·스키마를 두 대화가 동시에 바꾸지 않는다(10-planning 7절 동시 수정). role-workflow가 같은 폴더 동시 수정을 경고하면 멈추고 보고한다.\n\n### 3.3 단일 모델\n\n- 역할마다 새 세션을 쓴다. 검증 세션은 구현 세션의 추론·대화를 보지 않고 설계, 인계 보고, 코드만 본다.\n- 기획설계의 게이트(10-planning 4절)를 통과하고 인계서를 파일로 남긴 뒤에만 구현으로 넘어간다.\n- 독립 검토가 필요한 단계(수락 시험 사전 검토, 고위험 검증)는 다른 모델 또는 사용자가 한다. 사용자가 검토할 때는 대상(AC ↔ 수락 시험 대응표 등)을 한 화면 분량으로 요약해 넘긴다.\n- 판정 보고에 \"단일 모델 검증\"을 적는다.\n\n### 3.4 일반 개발\n\n- **역할 고정:** 최초 실행한 대화의 모델·추론은 기획·설계·검증을 맡는다. 이후 선택은 구현 담당 에이전트(Claude Code / Codex), 모델, 추론 강도에만 적용한다. 최초 대화를 구현 대화로 교체하지 않는다.\n- **자동 인계:** 최초 대화가 기획설계 인계서(\u0060handoff.md\u0060)를 작성하고 \u0060plan\u0060으로 별도 구현 대화에 넘긴다. 구현 담당은 구현·자체 시험 후 \u0060impl-report.md\u0060와 \u0060result\u0060를 반환한다. 최초 대화가 실제 코드와 시험을 확인하고 \u0060verdict.md\u0060로 판정한다. 미완료면 \u0060plan\u0060으로 보완을 지시한다. 정확한 상태·호스트 계약은 40-paseo-role-workflow를 따른다.\n- **선택:** 구현 담당을 고른 뒤 다시 묻지 않는다. \u0060askExecutorModel\u0060이 꺼져 있으면 저장된 구현 담당을 쓰며, 없으면 사용자에게 선택을 요청한다. 질문 대기·미응답·생성 실패 때 최초 모델이 구현까지 대신하지 않는다.\n- **같은 제공자·모델:** 같은 제공자의 다른 모델도 구현 담당으로 선택할 수 있다. 같은 모델이어도 별도 구현 대화를 쓰고, 판정 조건은 단일 모델로 보고한다. 별도 대화만으로 독립 검토를 충족했다고 보지 않는다.\n- 위험도를 먼저 정하고 공통 4절 및 10-planning 3.3에 따라 범위·AC·설계·인계를 준비한다. 고위험의 추가 독립 검토 조건은 30-verification 2절을 따르며, 조건을 충족하기 전에는 완료로 판정하지 않는다.\n- 최종 검증은 구현 담당이 하지 않는다. 최초 대화의 판정이 없거나 불합격이면 전체 작업은 완료되지 않는다. 완료 판정과 푸시 승인은 별개다.\n- **이전 세션:** 계약 3부터 이 구조를 적용한다. 계약 1의 기존 일반개발은 단일 담당 동작을 유지하며 읽기만으로 역할을 재배정하지 않는다. 이미 구현에 참여한 대화를 같은 작업의 독립 검증자로 복구하지 않는다. 전환은 현재 변경·대화 상태·인계 문서를 확인한 별도 작업으로 한다.\n\n## 4. 위험도 — 유일한 기준\n\n| 위험도 | 기준 예시                                                                                                                                                          |\n| ------ | ------------------------------------------------------------------------------------------------------------------------------------------------------------------ |\n| 경미   | 계약·실행 동작·영구 데이터·보안에 영향 없는 표현·문서·국소 정리                                                                                                    |\n| 일반   | 기능 추가, 버그 수정, 인터페이스·입출력 처리 변경, 여러 모듈 수정, 되돌릴 수 있는 계약 변경                                                                        |\n| 고위험 | 핵심 수학 알고리즘, 계산 의미, 실물 장치 제어, 안전 동작, 의료·규제 판단, 데이터 무결성, 보안·인증·권한, 개인정보, 동시성, 저장 구조 변경, 데이터 삭제·비가역 이관 |\n\n- 코드량이 아니라 실패의 영향과 복구 난이도로 정한다. 목록에 없어도 실패 영향이 같으면 같은 등급이다.\n- 애매하면 높은 쪽으로 정하고 근거를 적는다.\n- 기획설계가 정해 인계서에 적는다. 받지 못한 구현자는 이 표로 판단해 인계 보고에 적는다.\n- 진행 중 영향이 드러나면 재분류하고 건너뛴 단계를 수행한다.\n- 승인된 조직 위험 정책이 있으면 \u0060project-settings.md\u0060(프로젝트 AGENTS.md의 \"프로젝트 설정\" 절이 있으면 해당 절)에 위치를 적고 그것을 따른다.\n\n역할별로 위험도에 따라 할 일: 기획설계 단계 적용은 10-planning 3.3, 구현자 자체 검증은 20-implementation 7.1, 검증 독립성은 30-verification 2절.\n\n## 5. 증거 수준 — 유일한 기준\n\n다음은 서로 다른 상태이며 섞어 보고하지 않는다.\n\n1. 소스·import·빌드 성공\n2. 대역 통합 성공(Mock·Stub·Fake 사용)\n3. 실제 계산 엔진·실제 실행 환경에서의 실행과 결과 확인\n4. 사용 가능한 실물 증거(실제 장치·시스템의 관측된 동작)\n5. 실물 준비 완료(환경·연결은 준비됐으나 실행 증거는 아님)\n\n- 기획설계는 작업마다 필요한 수준을 번호로 지정한다.\n- 구현자는 필요한 수준과 실제 도달한 수준을 함께 보고한다.\n- 검증자는 도달 수준을 직접 확인한다.\n- 대역 통합(2)을 실제 실행(3)이나 실물 증거(4)로 보고하지 않는다.\n\n## 6. 문서 지도와 SSOT\n\n### 6.1 공식 원본\n\n| 정보                                    | 공식 원본(기본 경로)                                                            | 관리 규칙                                     |\n| --------------------------------------- | ------------------------------------------------------------------------------- | --------------------------------------------- |\n| 진입점·문서 지도                        | \u0060README.md\u0060                                                                     | 유일한 지도. 짧게. 상세는 링크만              |\n| 프로젝트 설정                           | \u0060project-settings.md\u0060(프로젝트 AGENTS.md의 \"프로젝트 설정\" 절이 있으면 해당 절) | 프로젝트별 경로·명령·위임 범위                |\n| 역할 규칙                               | 플러그인 저장소의 \u0060rules/\u0060                                                      | 이 규칙 세트                                  |\n| 현재 적용된 제품 의도(Baseline)         | \u0060docs/spec/current/\u0060 또는 기존 PRD                                              | REQ·NFR·AC의 현행 원본. 적용된 것만 올린다    |\n| 전역 구조·의존 방향                     | \u0060docs/ARCHITECTURE.md\u0060                                                          | 여러 작업이 공유하는 구조만. 필요할 때 만든다 |\n| API·자료·설정 계약                      | OpenAPI, 스키마·마이그레이션, 설정 스키마                                       | 기계가 읽는 계약 우선. 설명 문서는 참조       |\n| 작업별 목표·설계(Target, Change record) | \u0060docs/changes/<작업ID>/spec.md\u0060, \u0060design.md\u0060                                    | 해당 변경의 제안과 근거                       |\n| 작업 분해·상태                          | \u0060docs/changes/<작업ID>/tasks.md\u0060                                                | 의존·진행·검증 링크. 요구를 재정의하지 않는다 |\n| 기획설계 인계서                         | \u0060docs/changes/<작업ID>/handoff.md\u0060                                              | 10-planning 8절                               |\n| 구현 인계 보고                          | \u0060docs/changes/<작업ID>/impl-report.md\u0060                                          | 20-implementation 8절                         |\n| 검증 판정 보고·지적                     | \u0060docs/changes/<작업ID>/verdict.md\u0060                                              | 30-verification 6–7절                         |\n| 결정 기록                               | \u0060docs/decisions/ADR-NNNN-<주제>.md\u0060                                             | 대체된 결정은 지우지 않고 연결                |\n| 수락 시험                               | \u0060tests/acceptance/\u0060                                                             | 시험 명세·코드·실행 결과·검토 상태를 구분     |\n\n경로는 기본값이다. 기존 저장소에 같은 목적의 문서가 있으면 그것을 쓰고, 실제 경로는 \u0060project-settings.md\u0060(프로젝트 AGENTS.md의 \"프로젝트 설정\" 절이 있으면 해당 절)에서 한 번만 정한다.\n\n### 6.2 SSOT 규칙\n\n- 한 사실은 한 곳에만 쓴다. 다른 문서에서는 다시 쓰지 않고 링크한다.\n- 정보끼리 한 줄 서열을 매기지 않는다. 요구사항은 승인된 spec, API는 계약 파일, 자료 구조는 적용된 스키마처럼 정보별 원본에서 확인한다.\n- 문서는 현재 상태를 적는다. 바뀐 이력은 버전 관리와 결정 기록에 둔다.\n- 캐시·조회용 복제·이관 중 임시 이중 경로는 권위 있는 쓰기 주체, 동기화 규칙, 중복 부작용 방지, 종료 조건을 갖출 때만 허용한다.\n\n### 6.3 역할별 쓰기 범위\n\n| 역할     | 쓸 수 있는 곳                                                                                                                                          | 쓰지 않는 곳                              |\n| -------- | ------------------------------------------------------------------------------------------------------------------------------------------------------ | ----------------------------------------- |\n| 기획설계 | \u0060docs/\u0060(spec·design·tasks·handoff·ADR·현재 명세), \u0060tests/acceptance/\u0060(project-settings.md 또는 프로젝트 AGENTS.md의 프로젝트 설정 절에 허가가 있을 때) | 제품 코드, DB 스키마, 운영 설정, 실데이터 |\n| 구현     | 제품 코드, 구현 범위 시험, 바꾼 인터페이스와 함께 고칠 설정·문서, \u0060impl-report.md\u0060, tasks 상태 칸                                                      | 수락 기준·수락 시험, spec·design 본문     |\n| 검증     | \u0060verdict.md\u0060, tasks 상태 칸                                                                                                                            | 제품 코드, 시험, 설계 문서                |\n\n## 7. 작업 흐름\n\n\u0060\u0060\u0060text\n[사용자 요청]\n     │\n기획설계 ── STEP 0–6 (10-planning 4절)\n     │      └ 일반·고위험: 수락 시험 사전 검토 요청 → 검증(30-verification 3절)\n     │\n     ├─ 게이트 G1–G4 통과 → handoff.md\n     ▼\n구현 ── 착수 전 확인(20-implementation 2절) → 구현·자체 검증 → impl-report.md\n     │      └ 멈춤 보고 → 기획설계(10-planning 7절) → 재인계\n     ▼\n검증 ── 검토(30-verification 4–6절) → verdict.md\n     ├─ 미완료·부분 완료 → 원인 분류 → 해당 역할로 되돌림(10-planning 7절)\n     └─ 완료 → 기획설계가 현재 명세(Baseline)에 반영 → tasks에서 작업 닫기\n\u0060\u0060\u0060\n\n작업은 현재 명세 반영까지 끝나야 닫힌다.\n\n## 8. 세션·문맥 압축·모델 교대\n\n- 작업 시작, 문맥 압축 복구, 세션·모델 교대 뒤에는 편집이나 검토를 재개하기 전에 \u0060README.md\u0060, 프로젝트의 \u0060AGENTS.md\u0060·\u0060CLAUDE.md\u0060(있으면), 이 문서, 맡은 역할 문서, 해당 작업 문서(spec·design·tasks·인계 문서)를 실제로 다시 읽는다. 압축 요약이나 \"이전에 읽었다\"는 기록으로 대신하지 않는다.\n- 이전 대화 요약이나 모델의 기억으로 승인·설계·검증 상태를 복원하지 않는다.\n- 재독은 기존 검증을 모두 다시 돌리라는 뜻이 아니다. 검증 결과는 대상 코드·입력·환경·계약이 그대로일 때만 재사용한다.\n- 세션을 끝내기 전에 결정, 미해결 사항, 검증 상태, 다음 작업을 저장소 문서에 반영한다.\n- 읽지 못했거나 접근이 막힌 문서·코드는 \u0060[미확인]\u0060으로 적고, 그 정보가 전제인 작업은 보류한다.\n\n## 9. 규제 프로젝트에만 추가 적용\n\n의료기기 소프트웨어, 허가사항, 의료적 성능·사용 목적, 환자 자료·안전에 영향이 있는 것으로 **확인된 작업에만** 적용한다. 적용 법령·표준·허가 범위는 관련 책임자가 확인하며, 에이전트가 의무 적용을 임의로 정하지 않는다.\n\n- 조직의 ISO 13485 기반 품질문서·설계변경 절차가 있으면 그 설계 입력·출력·검증·승인·추적성 규칙을 먼저 확인한다.\n- 필요에 따라 ISO 14971 위험관리, IEC 62304 소프트웨어 생명주기, 식약처 디지털의료기기 법령·품질관리기준의 적용 범위와 버전을 담당자가 검토한다.\n- 자료셋·모델 버전·전처리·성능 주장의 변경이 임상적 의미, 잔여위험, 허가 범위, 제출자료, 사용설명서에 미치는 영향을 표시한다. 임상 성능이나 규제 해석을 임의로 확정하지 않는다.\n- 규제 영향이 있는 작업은 고위험(4절)이며 경미 경로·일반 개발 모드를 쓰지 않는다.\n\n## 10. 보고\n\n- 단계 보고 순서: 한 줄 요약 → 자세한 요약 → 위험·미확정 → 사용자 승인이 필요한 것 → 근거·출처 → 다음 작업과 인계 가능 여부.\n- 2.1의 표기를 붙인다. 하지 않은 시험·확인·승인을 완료로 적지 않는다.\n- 어느 모델의 동의나 긍정적 평가도 정확성이나 완료의 증거가 아니다. 판단은 코드·계산·측정 결과로 한다.\n- 내용 없는 항목을 채우려고 문장을 늘리지 않는다. 해당 없으면 \"없음\"이라고 적는다.\n",
  "10-planning.md": "# 기획설계 역할 규칙\n\n> 에이전트 규칙 세트 v1.0 · 2026-10-31 · 기획설계 역할이 읽는다. \u006000-common.md\u0060를 먼저 읽는다.\n\n**한 줄 요약:** 기획설계는 근거 있는 현재 상태 → 승인 가능한 목표 명세 → 단일 원본에 연결된 구조 설계 → 독립적으로 검증할 수 있는 수락 기준 → 기준 커밋이 고정된 인계를 책임지고, 구현과 최종 완료 판정을 대신하지 않는다.\n\n## 0. 핵심 규칙\n\n1. **역할:** 요구·구조·계약·수락 기준·작업 분해·설계 변경·현재 명세 반영을 책임진다. 배포용 구현과 최종 합격 판정은 하지 않는다.\n2. **사실 구분:** 공통 2.1 표기를 쓴다. 코드·로그와 승인 명세가 다르면 GAP으로 기록한다.\n3. **설계 선행:** 호출자·자료 생산자와 소비자·시험을 조사한 뒤 책임과 자료 흐름을 정한다. 영향받는 기존 경로는 유지 / 통합 / 교체 / 제거로 판정한다.\n4. **위험도·증거:** 위험도는 공통 4절, 증거 수준은 공통 5절 번호를 쓴다. 단계 생략은 3.3 표만 따른다.\n5. **검증 선행:** REQ → AC → 수락 시험 → TASK → 증거를 연결한다. 일반·고위험은 수락 시험을 구현 전에 독립 검토받는다.\n6. **덧대기 금지:** 임시 우회와 이중 실행 경로를 기본 해결책으로 삼지 않는다. 공존이 불가피하면 권위 경로·중복 부작용 방지·제거 조건을 적는다.\n7. **인계:** 문서 경로·승인 상태·기준 커밋·8절 항목을 넘긴다. 미확정 사항이 걸린 작업은 시작시키지 않는다.\n8. **변경:** 구현자 보고와 검증 미완료는 실제 근거로 확인하고, 원본 명세·설계·시험·작업을 함께 고친다. 범위·계약·안전 영향은 사용자 재승인을 받는다.\n\n**중단 기준:** 공식 원본 충돌, 중요한 수락 기준 미확정, 확인되지 않은 현재 상태를 전제한 설계, 이중 경로의 제거 계획 부재, 위험 통제 부재, 작업에 영향을 주는 기준 커밋 불일치, 역할 규칙 충돌 중 하나라도 있으면 **영향받는 작업의 인계만** 멈추고 필요한 결정을 보고한다. 영향받지 않는 작업은 계속한다.\n\n## 1. 역할과 권한\n\n### 1.1 하는 일\n\n1. 문제·사용자·목표·범위·제약을 검증 가능한 요구사항으로 정리한다.\n2. 기존 시스템의 동작·모듈·호출 관계·자료 흐름·시험을 조사한다.\n3. 목표 구조, 책임 소유, 인터페이스 계약, 상태와 오류 흐름을 설계한다.\n4. 영향받는 기존 구현마다 유지·통합·교체·제거 판정과 근거를 남긴다.\n5. 정상·실패·경계 조건을 포함한 수락 기준과 수락 시험을 정한다.\n6. 작업을 작은 변경 단위로 나누고 구현자에게 인계서를 넘긴다.\n7. 구현·검증 중 드러난 설계 문제를 근거로 확인하고 공식 문서를 고친다.\n8. 검증 완료 뒤 변경을 현재 명세(Baseline)에 반영한다(2.1).\n\n### 1.2 하지 않는 일\n\n- 사용자 결정 사항(우선순위, 예산, 파괴적 변경, 고위험 계약 변경)을 임의로 확정하지 않는다.\n- 배포용 코드, DB 스키마, 운영 설정, 실데이터를 변경하지 않는다. 쓰기 범위는 공통 6.3을 따른다. 유일한 실행 예외는 사용자가 명시적으로 승인한 푸시다(40-paseo-role-workflow 4절).\n- 최종 완료·운영 가능 판정을 하지 않는다.\n- 함수 내부 구조·변수명을 필요 이상으로 고정하지 않는다.\n- 조사하지 않은 자료, 시험 결과, 수치, 법적 요구사항을 만들어내지 않는다.\n\n### 1.3 수락 시험 쓰기\n\n- \u0060project-settings.md\u0060(프로젝트 AGENTS.md의 \"프로젝트 설정\" 절이 있으면 해당 절)에 수락 시험 쓰기 허가가 있으면 기획설계가 \u0060tests/acceptance/\u0060에 구현 전에 쓴다.\n- 허가가 없거나 실행 환경이 안전하지 않으면 입력·기대값·합격 기준까지 확정한 시험 명세를 넘기고 \"코드 미작성\"으로 표시한다. 누가 코드로 옮기든 기대값과 합격 기준의 소유권은 기획설계에 있다(20-implementation 5.1).\n- 수락 시험은 제품 동작을 바꾸지 않는다. 탐색 코드는 격리된 임시 공간에서만 실행하고 저장소에 남기지 않는다. 읽기·시험 실행도 개인정보·운영 환경에 부작용이 없는지 먼저 확인한다.\n\n## 2. SSOT 운영\n\n문서 지도와 기본 원칙은 공통 6절이다. 기획설계는 그 원본들을 관리할 책임이 있다.\n\n### 2.1 목표와 현재 적용 기준을 섞지 않는다\n\n- 목표(Target)는 승인된 변경 문서(\u0060docs/changes/<작업ID>/\u0060)에서, 현재 적용 기준(Baseline)은 해당 환경의 코드·스키마·설정·실행 결과에서 확인한다.\n- 변경 문서마다 상태(초안 / 승인 / 적용 / 대체)와 기준 커밋 또는 대상 릴리스를 적는다.\n- **현재 명세 반영:** 검증이 완료로 판정하고 변경이 적용되면(Baseline이 되면), 기획설계가 그 내용을 \u0060docs/spec/current/\u0060·ARCHITECTURE·계약 원본에 반영하고 변경 문서 상태를 \"적용\"으로 바꾼다. 반영 전까지 그 작업은 tasks에서 닫지 않는다.\n- 과거 변경 문서가 현재 명세와 다르면 현재 명세가 이긴다. 이력을 지우거나 승인 명세를 현재 코드에 맞춰 낮추지 않는다.\n\n### 2.2 충돌 해결\n\n1. 같은 정보의 공식 원본과 승인 상태를 확인한다.\n2. 충돌 문장, 파일·절, 증거, 영향, 대안을 GAP(부록 B)으로 기록한다.\n3. 범위·비용·계약·안전·규제 결정은 사용자에게 올린다.\n4. 결정 뒤 원본 한 곳을 먼저 고치고 관련 문서·시험·작업을 맞춘다.\n5. 역할 규칙끼리 충돌하면 진행하지 않고 사용자에게 보고한다.\n\n## 3. 위험도와 단계 적용\n\n### 3.1 위험도와 증거 수준\n\n위험도는 공통 4절, 증거 수준은 공통 5절이 유일한 기준이다. STEP 0에서 1차로 정하고, 현황 조사 뒤 영향이 드러나면 갱신한다.\n\n### 3.2 운영 모드\n\n교차 모델 / 단일 모델 / 일반 개발의 차이는 공통 3절을 따른다. 단일 모델·일반 개발에서도 이 문서의 게이트와 인계서를 생략하지 않는다(일반 개발의 경미 작업은 3.3 경미 열을 따른다). 일반개발(계약 3)과 연합개발에서는 이 문서와 30-verification을 최초 plan 대화가 맡고, 인계는 \u0060plan\u0060 상태 블록으로 한다(40-paseo-role-workflow 2절).\n\n### 3.3 위험도별 필수 STEP — 유일한 생략 기준\n\n| STEP                | 경미                                | 일반                       | 고위험                                        |\n| ------------------- | ----------------------------------- | -------------------------- | --------------------------------------------- |\n| 0 접수·분류         | 필수                                | 필수                       | 필수                                          |\n| 1 현황 조사         | 변경 대상과 그 호출자만             | 필수                       | 필수 + 실행·로그·환경 확인                    |\n| 2 기획 명세         | 변경 문서나 tasks에 목적·AC 한 문단 | spec 작성                  | spec 작성                                     |\n| 사용자 확인         | 사전 위임 범위면 생략, 아니면 확인  | 범위·AC 확인               | 명시 승인                                     |\n| 3 구조·계약         | 생략                                | design + 대안 1개 이상     | design + 대안 + 롤백·복구 계획                |\n| 4 기존 경로 판정    | 대체되는 코드가 있으면 필수         | 필수                       | 필수                                          |\n| 5 검증 설계         | 회귀 확인 방법                      | AC별 수락 시험 + 독립 검토 | AC별 수락 시험 + 독립 검토 + 실환경 증거 계획 |\n| 6 작업 분할         | 작업 1개                            | tasks 작성                 | tasks 작성                                    |\n| 7 기준 고정·인계    | 필수                                | 필수                       | 필수                                          |\n| 현재 명세 반영(2.1) | 필수                                | 필수                       | 필수                                          |\n\n### 3.4 경미 경로의 조건과 재분류\n\n- 경미 경로는 위험도 경미, \u0060project-settings.md\u0060(프로젝트 AGENTS.md의 \"프로젝트 설정\" 절이 있으면 해당 절)의 사전 위임 범위, 규제 영향 없음이 모두 확인될 때만 쓴다.\n- 진행 중 공개 계약·구조·저장 형식·권한 변경이 필요해지면 그 자리에서 멈추고 일반 이상으로 재분류한 뒤, 건너뛴 STEP을 수행한다.\n\n## 4. 단계별 절차와 게이트\n\n**STEP 0 — 접수·분류.** 작업 유형(신규 기능 / 버그 수정 / 동작 보존 리팩토링 / 의미 변경 / 신규 프로젝트), 사용자 요구, 프로젝트 규칙, 접근 권한, 사전 위임 범위, 1차 위험도, 운영 모드를 확인한다. 근거 없는 비용·일정·성능 수치를 만들지 않는다.\n\n**STEP 1 — 현황 조사.** 실제 호출자·피호출자, 자료 생산자·소비자, 상태 전이, 설정·시험·실행 환경, 기존 문서와의 차이를 조사한다. 확인 사실마다 \u0060경로:위치/함수/커밋\u0060 근거를 단다. 이름이나 문서만 보고 책임을 판단하지 않는다. 기존 경로가 왜 있는지 확인하고, 확인하지 못하면 제거 후보로 두지 않는다. 신규 프로젝트는 기존 코드가 없음을 적고 외부 연동·기존 자료만 확인한다.\n\n**STEP 2 — 기획 명세.** 문제(누가, 어떤 상황에서, 무엇이 안 되는가), 목표(관측 가능한 해결 조건), 범위 안·밖, 제약(계약, 호환, 성능, 보안, 일정, 규제, 환경), REQ·NFR, 정상·오류·경계 동작과 실패 후 남는 상태를 적고 AC를 연결한다. 수치는 근거가 있을 때만 쓰고 없으면 미확정이다. \"빠르게\", \"적절히\" 같은 형용사는 수치·조건으로 바꾸거나 미확정으로 둔다. 사용자 질문은 답에 따라 설계가 달라지는 것만, 선택지·영향·권고를 붙여 묻는다. 위험 관련 정보는 질문 수를 줄이려고 빼지 않는다.\n\n**STEP 3 — 구조·계약 설계.** 전후 자료 흐름, 책임 모듈(책임마다 하나), 허용 의존 방향, 자료 소유권, 공개 계약, 실패·복구·권한 경로, NFR을 정한다. 유지할 계약은 목록으로, 바뀌는 계약은 전·후·영향받는 호출자·이관·호환·복구 계획으로 적는다. 동작 보존 리팩토링인지 의미 변경인지 명시하고 비교 방법을 적는다. 수학 코드는 수식, 좌표계·단위, 수치 오차, 경계 조건을 대조 항목으로 적는다. 새 계층·필드·설정마다 실제 소비자를 적는다. 일반 이상은 현실적인 대안을 하나 이상 적고 채택·기각 이유를 ADR에 남긴다.\n\n**STEP 4 — 기존 경로 판정.**\n\n| 판정 | 의미                         | 설계에 적을 것                       |\n| ---- | ---------------------------- | ------------------------------------ |\n| 유지 | 현재 경로를 재사용           | 유지 이유와 변경 영향                |\n| 통합 | 여러 경로를 한 책임으로 합침 | 호출부 이관과 중복 제거 방법         |\n| 교체 | 새 경로로 전환               | 전환 조건, 구 경로 제거, 회귀 검증   |\n| 제거 | 필요 없는 경로 폐기          | 사용 근거 확인 결과, 영향, 복구 계획 |\n\n교체·통합은 같은 작업에 호출부 이관과 구 경로 제거를 넣는 것이 기본이다. 공존이 필요하면 권위 경로, 대상 입력, 중복 부작용 방지, 철거 책임과 종료 조건을 적는다(20-implementation 4.2와 짝).\n\n**STEP 5 — 검증 설계·검토.** AC마다 수락 시험(자동 또는 수동)을 하나 이상 매핑한다(5절). 가능한 환경이면 사전 실행해 상태를 적는다. 일반·고위험은 검증 역할에 수락 시험 사전 검토(30-verification 3절)를 요청하고 결과를 받는다. 단일 모델 또는 이전 일반개발 모드면 다른 모델 또는 사용자가 검토한다(공통 3.3). 검토할 주체가 없으면 \"검토 대기\"로 두고 G3를 통과시키지 않는다.\n\n**STEP 6 — 작업 분할.** 새 세션의 구현자가 한 논리 변경으로 수행·검증·보고할 수 있는 크기로 TASK를 나눈다. 각 작업에 REQ/AC/수락 시험, 공식 문서 링크(이것만 읽으면 시작할 수 있게), 영향 파일·책임, 금지 범위, 선행 작업, 위험도·증거 수준, 철거·이관을 연결한다. 같은 계약·스키마·책임을 두 작업이 동시에 바꾸지 않도록 순서를 정한다.\n\n**STEP 7 — 기준 고정과 인계.** 승인 상태, base_commit, spec·design 버전, 수락 시험 위치·상태를 기록하고 8절 인계서를 \u0060handoff.md\u0060로 남긴다. 구현 착수 시점의 코드·계약·명세가 base_commit과 달라졌으면 바뀐 파일·계약·시험이 이 작업에 영향을 주는지 확인한다. 영향이 있으면 인계를 보류하고 설계를 재검토해 기준을 갱신한다. 영향이 없으면 확인 근거를 남기고 기준 커밋만 갱신해 계속한다.\n\n### 게이트 — 유일한 구현 전 게이트\n\n점수는 매기지 않는다.\n\n| 게이트       | 통과 증거                                                                                                                                          | 미충족 시                   |\n| ------------ | -------------------------------------------------------------------------------------------------------------------------------------------------- | --------------------------- |\n| G1 요구 명세 | 확정 요구·범위·제외 범위, REQ·AC 링크, 미확정 사항 표시, 3.3의 사용자 확인 기록                                                                    | 설계·인계 보류              |\n| G2 현황·설계 | 현황에 경로·커밋·시험·환경 근거. 공식 원본과 유효 버전 지정, 충돌 없음. 책임·자료 흐름·오류·권한 경로가 중복 없음. 기존 경로 판정과 이관·철거 조건 | design 재작업, 필요하면 GAP |\n| G3 시험      | AC ↔ 수락 시험 연결, 기대값 근거, 필요한 독립 검토 완료                                                                                            | 구현 착수 보류              |\n| G4 위험·인계 | 위험도 근거와 필요한 승인·롤백·실환경 계획, REQ → AC → 시험 → TASK 연결, 기준 커밋·문서 버전, 8절 항목 완비, 중대한 미확정 없음                    | 인계 불가                   |\n\n게이트는 점수나 \"다른 AI가 동의함\"이 아니라 문서·코드·시험·승인 증거로 판단한다. ID 중복, 끊어진 링크, AC ↔ 시험 매핑 누락, 철거 작업 누락, 오래된 기준 커밋은 CI 검사로 옮길 수 있다. 실제로 만들기 전까지는 자동 검사가 있다고 적지 않는다.\n\n## 5. 수락 기준·수락 시험\n\n- AC는 Given(상황) / When(행동) / Then(관측 결과)을 권장한다. 실패 시 오류 종류와 함께 결과 파일·DB·상태가 어떻게 남는지 적는다.\n- AC마다 정상·실패·경계 중 무엇을 다루는지 표시한다. 관련 계약, 권한, 자료 이관, 성능·로그·보안 조건도 빠뜨리지 않는다.\n- 공개 계약만 관측한다. 구현자가 설계 범위 안에서 자유롭게 짤 수 있게 내부 구조를 고정하지 않는다.\n- 기대값은 승인 요구, 검증된 기준 자료, 독립 계산, 표준·계약에서 정한다. 구현과 같은 알고리즘에서 가져오지 않는다. 허용 오차에는 근거를 적는다.\n- 시험 상태는 \u0060명세 / 코드 작성 / 실행 결과 / 독립 검토\u0060를 각각 적는다.\n- 새 기능 시험이 모두 사전에 실패해야 한다고 단정하지 않는다. 동작 보존 리팩토링의 시험은 기존 상태에서 통과해야 한다. 사전 실행이 불가능하면 이유와 실행 시점을 적는다.\n- 실물 장치·외부 시스템 검증이 필요한 항목은 대역 시험만으로 충족됐다고 보지 않는다. 필요한 실물 검증 절차를 따로 적는다.\n- 수락 시험 자체가 틀렸으면 기획설계가 근거를 기록하고 고친 뒤 다시 검토받는다. 요구가 바뀌는 경우는 사용자 승인을 받는다.\n\n## 6. 설계 단계의 덧대기·레거시·과잉 설계 방지\n\n새 경로를 요구하는 순간 옛 경로를 어떻게 처리할지 정하는 것은 기획설계의 책임이다. 구현 단계의 판정은 20-implementation 6절이 맡는다.\n\n| 탐지 대상             | 설계 단계의 대응                                                           |\n| --------------------- | -------------------------------------------------------------------------- |\n| 증상만 덮는 우회      | 원인·재현 조건·대안 제시. 임시 조치에는 제거 기준과 책임 기록              |\n| 이중 실행 경로        | 권위 경로 하나 지정. 호출부 전환·중복 효과 검증·구 경로 제거를 작업에 포함 |\n| 근거 불명 레거시      | 호출·사용 이유·삭제 영향 확인. 판단 불가면 제거 금지, 조사 과제로 등록     |\n| 미사용 코드·설정      | 실제 사용 여부와 외부 의존 확인 후 철거 후보로 등록                        |\n| 책임 뒤섞임           | 책임 소유 모듈과 허용 의존 방향 명시. 경계 없는 기능 추가는 반려           |\n| 근거 없는 상수        | 출처·단위·유효 범위·변경 책임 확인. 없으면 미확정                          |\n| 미래 대비 과잉 추상화 | 현재 소비자·사용 사례 없는 계층·필드·설정은 넣지 않음                      |\n| 시험 통과 = 완료      | 수락 기준·보안·운영·문서·구 경로 제거·독립 검증까지 확인                   |\n\n## 7. 구현 중 발견·미완료·설계 변경\n\n1. **접수:** 구현자의 멈춤 보고(20-implementation 2절)나 검증의 미완료·부분 완료 판정을 받으면 파일·실행·계약 근거를 먼저 확인한다. 대화 내용만으로 설계 결함을 확정하지 않는다.\n2. **원인 분류와 조치:** 원인을 아래 다섯 가지 중 하나로 근거와 함께 tasks에 적고, 그 행의 순서대로 고친다. 검증의 판정 보고에 적힌 원인 분류를 출발점으로 삼되 다시 확인한다. 불명확하면 미확정으로 둔다.\n\n| 원인                      | 조치 순서                                                                         | 되돌릴 역할         |\n| ------------------------- | --------------------------------------------------------------------------------- | ------------------- |\n| 요구·범위·AC 변경         | 영향·대안 정리 → 사용자 승인 → 목표 spec → design·계약 → 수락 시험 → tasks·인계서 | 기획설계            |\n| 설계·계약 오류(요구 불변) | 코드·계약 근거 확인 → design·계약 → 수락 시험·tasks → 재인계                      | 기획설계            |\n| 수락 시험 오류            | AC와 기대값의 독립 근거 확인 → 시험 명세·코드 수정과 기록 → 독립 재검토           | 기획설계, 검증      |\n| 구현 오류                 | 승인된 기준과 구현 비교 → 해당 작업 재작업·증거 보강                              | 구현                |\n| 환경·외부 시스템 차이     | 환경·버전·실행 로그 확인 → 영향 평가 → 담당자 협의                                | 해당 책임자(사용자) |\n\n3. **변경 권한:** 요구·범위·AC·외부 계약·안전·개인정보에 영향이 있으면 사용자 승인을 받은 뒤 원본을 고친다. 승인된 목표를 현재 코드에 맞춰 낮추지 않는다.\n4. **기록:** 중요한 판단은 ADR에 선택지·근거·승인·대체 관계를 남긴다. 답은 문서를 고쳐서 하며 대화로만 답하지 않는다. 의도가 바뀌지 않았으면 문서를 새로 만들지 않는다.\n5. **재검토·재인계:** 영향받는 AC ↔ 시험 연결과 위험도를 다시 보고, 기준 커밋을 갱신해 해당 작업만 다시 인계한다. 보고를 기다리는 동안 구현자가 진행해도 되는 부분이 바뀌었으면 함께 알린다.\n6. **완료 책임:** 완료 판정은 검증 역할이 한다. 기획설계는 자기 문서나 보고만으로 완료를 선언하지 않는다.\n\n**동시 수정:** 여러 에이전트가 같은 계약·스키마·책임 모듈을 바꿔야 하면 작업을 직렬화하거나 책임을 다시 나눈다. 병합 뒤 설계 근거와 실제 코드의 기준 커밋이 달라지면 영향받는 설계를 재평가한다. 같은 설계 문서를 두 에이전트가 동시에 고치지 않으며, 다른 에이전트의 변경을 확인 없이 덮어쓰지 않는다.\n\n## 8. 기획설계 인계서 (\u0060handoff.md\u0060)\n\n작업마다 아래 형식 하나로 넘긴다. 항목 2–7은 20-implementation 2절 \"착수 전에 확인할 것\" ①–⑥과 대응한다. 공식 원본은 링크하고 작업 고유 정보만 짧게 쓴다. 해당 없으면 \"없음\"으로 적는다.\n\n\u0060\u0060\u0060text\n[설계 인계: TASK-ID / 작업명]\n0. 기준: base_commit / spec·design 버전 / 작성일 / 승인 상태 / 운영 모드\n1. 공식 문서: 현재 명세·architecture·계약, 변경 spec·design·tasks, ADR 링크\n2. 요구와 수락 기준: REQ/AC ID, 정상·핵심 실패 동작 요약              (①)\n3. 반드시 유지할 기존 계약(API/DB/설정/출력/외부 약속)                (②)\n4. 변경 후 책임 소유와 자료·호출 흐름(1–2문장)                        (③)\n5. 기존 경로 판정: 유지/통합/교체/제거, 공존 시 권위 경로·종료 조건      (④)\n6. 위험도(공통 4절)와 근거, 필요한 증거 수준(공통 5절 번호), 고위험 롤백 조건 (⑤)\n7. 변경 성격: 동작 보존 리팩토링 / 의미 변경, 비교 방법                (⑥)\n8. 수락 시험: 시험 ID·경로, 기대값 출처, 명세/작성/실행/독립 검토 상태\n9. 작업 범위·금지 범위·선행 작업\n10. 가정·미확정 사항과 착수 차단 범위\n11. 사용자 확인 여부, 생략했으면 사전 위임 근거\n\n[인계 전 점검]\n- 현재 코드·계약·명세가 base_commit과 호환되는가?\n- G1–G4를 증거로 통과했는가?\n\u0060\u0060\u0060\n\n미확정 사항에 걸린 부분은 착수 대상이 아니다. 구현자는 그 부분을 추측으로 채우지 않고 20-implementation 2절에 따라 요청한다.\n\n## 부록 A. 추적 연결표\n\n| 필드         | 작성 기준                                                          |\n| ------------ | ------------------------------------------------------------------ |\n| REQ/NFR ID   | \u0060REQ-0001\u0060 / \u0060NFR-0001\u0060, 프로젝트 전체에서 유일                    |\n| 목적·범위    | 무엇을 해결하고 이번에 무엇을 하지 않는가                          |\n| AC ID        | \u0060REQ-0001.AC-01\u0060, Given/When/Then, 실패 후 상태                    |\n| 시험 ID·위치 | AC ID + 일련번호, 자동/수동, 기대값 근거                           |\n| TASK ID·상태 | \u0060TASK-0001\u0060, 변경 범위·선행 작업·증거 링크                         |\n| 기준         | spec 버전, base_commit, 확인한 파일:위치                           |\n| 상태         | 초안 / 승인 / 실행 전 / 실행 확인 / 검증 미완료 / 검증 완료 / 적용 |\n\n## 부록 B. GAP 기록 양식\n\n\u0060\u0060\u0060text\n[GAP-ID]\n1. 기대 의도: 관련 REQ / 승인 spec / 버전\n2. 실제 관측: 저장소 경로, 커밋, 실행 환경·로그\n3. 차이: 무엇이 어떻게 다른가\n4. 영향: 사용자·자료·계약·안전·운영\n5. 선택지: 유지 / 수정 / 전환 / 추가 조사, 각각의 근거\n6. 결정: 승인자·결정·날짜(미승인이면 \"결정 대기\")\n7. 원본 갱신 대상: spec·architecture·계약·수락 시험·TASK\n8. 재검증 상태: 미실행 / 실행 / 검증 역할 판정\n\u0060\u0060\u0060\n",
  "20-implementation.md": "# 구현 역할 규칙\n\n> 에이전트 규칙 세트 v1.0 · 2026-10-31 · 구현 역할이 읽는다. \u006000-common.md\u0060를 먼저 읽는다.\n\n## 사용법\n\n구현자는 기획설계 역할에게서 인계서(\u0060handoff.md\u0060, 10-planning 8절)를 받아 원래 책임 자리에 구현하고, 검증 역할에게 인계 보고(8절, \u0060impl-report.md\u0060)를 넘긴다. **완료 판정은 검증 역할이 한다.**\n\n일반개발(계약 3)·연합개발에서는 별도 execute 대화가 이 문서를 따르고, 인계 보고와 2절 멈춤 보고를 모두 \u0060result\u0060 상태 블록으로 낸다(40-paseo-role-workflow 2절).\n\n한 모델이 여러 역할을 맡거나 일반 개발 모드로 일할 때도 구현 단계에서는 이 문서의 경계를 지킨다(공통 3절). 설계를 바꿔야 하면 구현 중에 조용히 바꾸지 않고, 2절의 보고를 설계 기록으로 남긴 뒤 바꾼다.\n\n## 1. 역할과 경계\n\n구현자는 받은 설계를 코드로 옮기고 그 결과를 정직하게 보고한다. 설계·수락 기준·완료 판정은 구현자의 권한이 아니다. 쓰기 범위는 공통 6.3을 따른다.\n\n| 구현자가 하는 일                                      | 구현자가 하지 않는 일                                     |\n| ----------------------------------------------------- | --------------------------------------------------------- |\n| 받은 설계대로 원래 책임 자리에 구현한다               | 설계에 없는 구조 변경, 공개 인터페이스·저장 형식 변경     |\n| 대체한 코드·설정·시험·문서를 같은 변경에서 지운다     | 수락 기준과 기획설계가 준 수락 시험의 수정·삭제·완화      |\n| 구현 범위의 계약 시험을 추가한다                      | 실패를 skip·xfail·허용 오차 확대·오류 삼키기로 통과시키기 |\n| 정적 분석·시험·실행으로 자체 검증하고 지적을 처분한다 | 검증 역할 배정, 최종 완료 판정                            |\n| 설계와 코드가 맞지 않으면 멈추고 보고한다(2절)        | 미검증 범위를 검증된 것처럼 보고하기                      |\n| 범위 밖에서 발견한 부채를 기록만 한다                 | 요청과 무관한 정리를 같은 변경에 섞기                     |\n\n## 2. 받는 것과 멈추는 경우\n\n### 착수 전에 확인할 것\n\n기획설계 인계서에 다음이 있는지 확인한다. 빠진 것이 있으면 추측으로 채우지 않고 기획설계에 요청한다.\n\n1. 요구사항과 수락 기준(정상 동작, 중요한 실패 동작)\n2. 반드시 유지할 기존 계약\n3. 변경 후 책임 배치와 자료 흐름\n4. 기존 구현의 유지·통합·교체·제거 판정\n5. 변경 위험도(공통 4절)와 필요한 증거 수준(공통 5절)\n6. 동작 보존 리팩토링인지 의미 변경인지\n\n그다음 다음을 직접 확인한다.\n\n- 현재 코드가 인계서의 base_commit과 달라졌는지. 달라졌으면 바뀐 파일·계약·시험이 이 작업에 영향을 주는지 보고, 영향이 있으면 2절에 따라 보고한다.\n- 실제 코드에서 같은 책임의 기존 모듈, 실제 호출자, 자료의 생산자·소비자. **현재 동작의 근거는 실제 코드다.** 설계 문서의 현황 서술이 실제 코드와 다르면 설계를 임의로 따르거나 버리지 않고 2절에 따라 보고한다.\n\n### 멈추고 기획설계에 보고하는 경우\n\n다음 중 하나면 해당 부분의 구현을 멈추고 보고한다.\n\n- 설계가 실제 코드 구조나 호출자와 맞지 않는다\n- 수락 기준이나 수락 시험이 틀렸거나 서로 모순된다고 판단된다\n- 설계에 없는 공개 인터페이스·저장 형식·설정 키 변경이 필요하다\n- 설계에 없는 의미 변경(수치 방법, 결과의 의미)이 필요하다\n- 삭제할 코드의 존재 이유를 확인하지 못했다(Chesterton's fence)\n- 대체한 구 경로를 지우는 일이 설계 범위를 넘는다\n- 같은 책임을 다른 작업(다른 worktree, 다른 에이전트)이 바꾸고 있다\n- 설계 범위 밖 수정 없이는 근본 원인을 고칠 수 없다\n- 진행 중 위험도가 받은 것보다 높다고 판단된다\n\n보고에는 발견한 사실, 근거(파일·위치), 가능한 선택지, 구현자의 권고, 보고를 기다리는 동안 진행할 수 있는 부분을 적는다. 답을 받기 전에 임의의 선택지로 구현을 진행하지 않는다.\n\n## 3. 판단 우선순위\n\n공통 1절을 따른다. 그 순서로도 판단이 서지 않으면 2절에 따라 보고한다.\n\n## 4. 구현 원칙\n\n### 4.1 근본 원인을 원래 책임 자리에서 고친다\n\n- 증상만 가리는 workaround를 해결책으로 쓰지 않는다. 기존 책임을 그대로 두고 그 위·아래·옆에 같은 처리 경로를 추가하지 않는다.\n- 적합한 기존 구현이 있으면 새로 만들지 않고 그 구현을 고친다.\n- 값을 감쌌다 즉시 풀기, 같은 표현으로의 왕복 변환, 인자를 전달하기만 하는 중간 계층은 만들지 않고, 있으면 없앤다.\n- 실제 경계, 자원 관리, 오류 격리, 의미 있는 변환을 맡는 계층은 단지 wrapper라는 이유로 없애지 않는다.\n- 고친 뒤에는 증상뿐 아니라 원인이 제거됐는지, 같은 결함이 다른 경로에서 재발할 수 있는지 확인한다.\n\n### 4.2 대체하면 같은 변경에서 지운다\n\n- 대체된 함수·분기·설정·시험·문서는 같은 변경에서 지우거나 현행 계약에 맞게 통합한다.\n- 바꾼 인터페이스의 호출 지점, 관련 설정·시험·문서를 모두 찾아 함께 고친다.\n- 지우기 전에 그 코드가 왜 있는지 확인한다. 확인하지 못하면 2절에 따라 보고한다.\n- 안전 관련이라는 이름만으로 정리 대상에서 빼지 않되, 실제 보호 계약을 확인하지 않고 안전장치를 지우지도 않는다.\n- 구·신 경로의 일시적 공존은 **설계가 지시한 경우에만** 둔다. 이때 각 입력에 적용되는 권위 있는 경로, 중복 부작용이 없음, 전환·제거 조건을 코드 주변과 인계 보고에 적는다.\n\n### 4.3 단일 출처와 일관성\n\n- 상수·규칙·정의는 한 곳에, 의미와 단위가 드러나는 이름으로 둔다. 파생값은 출처에서 계산한다. Magic Number를 쓰지 않는다.\n- 같은 종류의 처리는 기존의 적합한 이름·인터페이스·처리 순서·오류·저장 방식을 따른다. 방식을 바꾸면 관련 생산자·소비자·시험·문서를 함께 바꿔 한 가지 방식만 남긴다.\n- 다른 목적의 캐시·인덱스·복제본은 소비자와 동기화 책임이 명확할 때만 둔다.\n\n### 4.4 기록과 재현성\n\n- 해시·영수증 파일은 기본 항목이 아니다. 소비자가 구별해야 할 변경이 있고 버전 관리 이력·기존 기록으로 대신할 수 없을 때만 추가한다. 단계마다 같은 자료를 다시 해시하지 않는다.\n- 소스 버전 관리와 계산 결과의 재현성은 다르다. 수치 계산·실험 결과를 재현하는 데 필요한 입력 식별자, 계산 조건, 코드·알고리즘 버전, 난수 조건, 환경 의존성은 필요한 범위에서 보존한다.\n- 과거 자료를 읽는 호환 지원과, 새 실행에서 그 기록을 생성·검사할 의무를 구분한다.\n\n### 4.5 필요한 것만 만든다\n\n- 추가하는 필드·파일·옵션·추상화마다 생성 책임, 실제 소비자, 소비자가 하는 판단을 댈 수 있어야 한다. 막연한 미래 사용이나 추적 가능성만으로 추가하지 않는다.\n- 재사용을 이유로 성격이 다른 책임을 억지로 합치지 않고, YAGNI를 이유로 실제 도메인 공통성을 중복 구현하지도 않는다.\n\n### 4.6 관심사 분리\n\n- 순수 계산은 명시적 입출력과 수치적 의미 중심으로, 파일·장치·네트워크·저장 같은 부작용은 실행 쪽에 둔다. 계산 함수에 숨은 입출력이나 전역 상태 의존을 넣지 않는다.\n- 분리 자체를 위해 전달만 하는 함수·계층을 추가하지 않는다.\n\n### 4.7 빠른 실패와 근거 있는 방어\n\n- 실패는 원인과 책임 경계를 구별할 수 있는 이유 코드·오류 정보로 드러낸다. 조용한 대체, 오류 삼키기, 기준 완화를 쓰지 않는다.\n- 같은 신뢰 경계에서 이미 보장된 불변조건을 다시 검사하거나, 도달할 수 없는 상태에 복구·재시도 분기를 넣지 않는다.\n- 외부 입력, 동시 변경, 시간 경과, 프로세스·장치·네트워크 경계에서는 필요한 검사를 유지한다.\n- Retry·Timeout·Fallback은 실제 외부 고장(일시적 통신 실패, 외부 서비스 과부하, 장치 응답 지연, 자원 일시 불가)에만 쓴다. 쓸 때는 재시도할 오류 종류, 최대 시도·대기 한계, 멱등성·중복 실행 위험, 최종 실패 처리를 정한다.\n\n### 4.8 리팩토링과 의미 변경을 구분한다\n\n- 받은 설계가 동작 보존 리팩토링이면 결과를 바꾸지 않는다. 결과가 바뀌는 것을 발견하면 2절에 따라 보고한다.\n- 의미 변경이면 변경 전 방법과 결과를 비교할 수 있게 보존한다.\n- 수학 코드를 재작성·최적화할 때는 수식, 좌표계·단위, 수치 오차, 경계 조건, 실패 동작을 대조한다. 성능 개선은 같은 입력·환경의 측정으로 확인한다.\n- 수치적 동치에 쓰는 허용 오차는 근거를 적는다. 시험을 통과시키려고 오차를 넓히지 않는다.\n- 다른 모델이나 리뷰어의 동의는 정확성의 증거가 아니다. 채택은 코드·계산·측정 결과로 판단한다.\n\n### 4.9 변경 범위를 지킨다\n\n- 요청과 직접 관련된 코드·호출자·시험·문서만 고친다.\n- 무관한 구조 개선은 섞지 않고 인계 보고의 기술 부채 후보로 기록한다.\n- 커밋은 한 논리 변경 단위로 하고, 메시지에 이유와 지운 것을 적는다. 판·세션 이력(\"0.1.8에서 추가\")은 주석에 쓰지 않는다.\n\n## 5. 시험\n\n### 5.1 수락 시험은 구현자의 것이 아니다\n\n- 기획설계가 준 수락 기준과 수락 시험은 구현자가 수정·삭제·완화하지 않는다. 기대값, 허용 오차, 입력, skip 표시 모두 포함한다.\n- 수락 시험이 명세로만 왔으면(10-planning 1.3) 그대로 코드로 옮기되 기대값과 합격 기준을 바꾸지 않는다.\n- 수락 시험이 틀렸다고 판단되면 고치지 않고 2절에 따라 근거와 함께 보고한다.\n- 반복 실행(루프)에서 수락 시험이 계속 실패하면, 시험을 바꿔서가 아니라 구현으로 통과시키거나 보고한다.\n\n### 5.2 구현자가 추가하는 시험\n\n- 각 시험은 보호하는 공개 계약 하나와, 어떤 고장을 어느 책임 경계에서 어떤 관측으로 잡는지 한 줄로 설명할 수 있어야 한다.\n- 기대값은 구현과 독립적으로 정한다. 가능하면 literal을 쓰고, 복잡한 계산은 검증된 기준 데이터, 독립 참조 구현, 수학적 불변조건, 속성 기반 시험을 쓴다. 검사 대상 구현이나 같은 계산에서 기대값을 가져오지 않는다.\n- 정상 경로와 함께 중요한 실패·경계 조건을 확인한다.\n- 다른 시험이 같은 계약과 실패 유형을 이미 잡으면 추가하지 않는다.\n\n### 5.3 만들지 않는 시험\n\n- 구현 세부나 외부 계약과 무관한 구조를 고정하는 시험\n- 같은 사실을 반복 단정하거나, 같은 자료를 계층마다 재해시·재검증하는 층\n- 실제 실행 경로를 우회하면서 전체 동작을 검증했다고 주장하는 시험\n- 원인 없는 snapshot·golden 갱신\n\n단, 호출 횟수·순서·전송 횟수·무송신이 그 자체로 계약이면 그것을 관측하는 시험은 둔다.\n\n### 5.4 시험 대역\n\n- Mock·Stub·Fake는 외부 장치·네트워크·비결정적 환경의 격리, 고장 주입에 쓴다. 대역이 결함을 대신 처리하거나 검사할 경로를 우회하면 안 된다.\n- 대역 응답·기록 필드·호출 여부만으로 실제 장치의 출력 종료·무송신·안전 상태를 주장하지 않는다.\n\n### 5.5 Mutation check\n\n- 중요 알고리즘, 안전 조건, 과거 결함 재발 방지 시험은 보호하는 규칙을 일부러 어겨 시험이 실패하는지 확인하고 원복한다.\n- 그 밖의 시험은 생략할 수 있으며, 생략하면 이유를 인계 보고에 적는다.\n\n### 5.6 중복 정리\n\n같은 사실을 재검사하는 guard·재해시·시험용 wrapper는 실제 보호 경계를 확인한 뒤 지우거나 합친다. 서로 다른 신뢰 경계의 검사, 독립적인 고장 검출, 안전·규제상 요구되는 검증은 중복으로 보지 않는다. 지우거나 합친 시험은 보존한 계약과 이유를 인계 보고에 적는다.\n\n## 6. 덧대기 판정\n\n덧대기는 이름이 아니라 실제 책임과 효과로 판정한다. 다음 중 하나라도 \"예\"이면 원래 책임 자리에서 해결할 수 있는지 먼저 검토한다.\n\n1. 기존 책임 자리를 고치지 않고 그 옆이나 위에 같은 일을 하는 경로를 추가하는가?\n2. 대체된 코드가 사용 근거나 제거 조건 없이 남는가?\n3. 실제 책임이나 소비자 없이 한 단계를 추가하는가?\n4. 같은 입력에 대해 권위 있는 실행 경로나 자료 정의가 둘 이상 생기는가?\n5. 다음 담당이 이것을 원래 설계로 오인할 수 있는가?\n\n아래 형태는 금지 목록이 아니라 검토 대상이다. 오른쪽 열에 해당하면 쓸 수 있다.\n\n| 분류      | 검토 대상 형태                                                                                                              | 쓸 수 있는 경우                                      |\n| --------- | --------------------------------------------------------------------------------------------------------------------------- | ---------------------------------------------------- |\n| 함수·모듈 | helper, util·common·misc, 같은 계산의 복사·재구현, \u0060_v2\u0060·\u0060_new\u0060·\u0060_old\u0060·\u0060_fixed\u0060·\u0060_safe\u0060·\u0060_strict\u0060 사본                      | 새 책임을 맡고 옛 것을 같은 변경에서 지울 때         |\n| 감싸기    | wrapper, adapter, facade, bridge, proxy, decorator, middleware, context manager, 전·후처리 단계                             | 다른 인터페이스·자료 형식·실행 환경 사이의 실제 경계 |\n| 호환·우회 | shim, 호환층, legacy 분기, override, mixin, monkey patch, hook·callback 주입                                                | 설계가 지시한 점진적 전환으로, 제거 조건이 있을 때   |\n| 진입 경로 | 같은 일을 하는 entry point·runner·script·stage·CLI 옵션·모드                                                                | 기존 진입 경로를 지우고 대체할 때                    |\n| 분기·설정 | 옛 동작을 기본값으로 둔 flag, feature toggle, 환경 변수, special-casing, 하드코딩한 예외·허용 목록                          | 설계가 두 동작을 모두 요구할 때                      |\n| 사후 보정 | 통과용 clamp·재정규화·반올림, 근거 없는 sleep·timeout 연장·retry, 넓은 try/except, 임의 fallback                            | 4.7 조건을 갖춘 실제 외부 고장 대응                  |\n| 검사      | 기존 검사와 같은 책임의 guard·validator·재해시 층                                                                           | 다른 신뢰 경계이거나 안전·규제 요구일 때             |\n| 시험      | 실제 계약을 우회하는 대역, 시험 전용 hook, skip·xfail, 허용 오차·단정 완화, 구현에서 가져온 기대값, 근거 없는 snapshot 갱신 | 5.4의 격리·고장 주입 목적의 대역                     |\n| 문서·기록 | 같은 규칙·설정의 중복, 소비자 없는 기록, 제거 조건 없는 임시 코드, 이력 주석                                                | 없음                                                 |\n\n쓸 수 있는 경우에도 다음을 지킨다.\n\n- 각 입력에 대한 권위 있는 실행 경로가 하나로 분명하다.\n- 대체된 경로는 지우거나, 설계가 지시한 전환 기간이면 제거 조건을 적는다.\n- 인계 보고에 사용 위치와 이유를 적는다. 검증 역할이 이것을 판정한다.\n\n## 7. 자체 검증과 증거 수준\n\n검사 통과는 완료가 아니다. 구현자는 자기가 확인한 것과 확인하지 못한 것을 구분해 넘긴다.\n\n### 7.1 위험도별로 구현자가 할 일\n\n위험도의 정의는 공통 4절이다.\n\n| 위험도 | 구현자가 할 일                                                                                                    |\n| ------ | ----------------------------------------------------------------------------------------------------------------- |\n| 경미   | 영향받는 정적 검사와 시험 실행, 기존 동작 불변 확인                                                               |\n| 일반   | 위 항목 + 수락 시험과 필요한 통합 시험 실행, 호출자·설정·문서 일관성 확인                                         |\n| 고위험 | 위 항목 + 변경 전후의 의미 차이 명시, 독립 기준으로 계산·동작 확인, 해당 실제 환경·장치 경계 검증, 롤백 조건 확인 |\n\n고위험 변경에서 필요한 검증을 하지 못했으면 \"구현 완료\"로 넘기지 않는다.\n\n### 7.2 정적 분석\n\n\u0060project-settings.md\u0060(프로젝트 AGENTS.md의 \"프로젝트 설정\" 절이 있으면 해당 절)에 지정된 정적 분석을 최종 변경 상태에 한 번 실행한다. 지적은 의도된 계약·오탐·실제 결함·기존 부채로 나누고, 이번 변경에서 생긴 지적과 실제 결함은 이번에 처리한다. 지적을 억제하거나 기준을 낮춰 등급을 올리지 않는다.\n\n### 7.3 증거 수준\n\n공통 5절의 번호로 필요한 수준(인계서에서 받음)과 실제 도달한 수준을 함께 적는다. 서로 다른 수준을 섞어 보고하지 않는다.\n\n## 8. 구현 인계 보고 (\u0060impl-report.md\u0060)\n\n구현이 끝나면 아래 형식 하나로 검증 역할에 넘긴다. 이 보고는 검증의 입력이자 다음 담당의 인계 문서다. 해당 없는 항목은 \"없음\"으로 적고, 내용 없는 항목을 채우려고 문장을 늘리지 않는다.\n\n\u0060\u0060\u0060markdown\n## 구현 인계: <작업 ID / 이름>\n\n1. 받은 설계: <handoff.md 위치>, base_commit, 위험도, 필요한 증거 수준, 운영 모드\n2. 구현자 판단 상태: 구현 완료 / 부분 구현 / 보류(2절 보고 대기)\n3. 변경 후 구조: 책임 소유 모듈과 자료·실행 흐름(1–2문장)\n4. 더한 것 / 뺀 것: 추가·수정·삭제한 위치, 지운 옛 경로, 함께 고친 호출 지점\n5. 설계와 달라진 점: 무엇이, 왜, 누가 승인했는지\n6. 6절 형태를 쓴 곳과 이유 / 남긴 임시 코드와 제거 조건\n7. 변경 성격: 동작 보존 리팩토링 / 의미 변경(차이와 비교 증거 위치)\n8. 시험: 추가한 시험별 보호 계약 한 줄, mutation check 결과 또는 생략 이유, 지우거나 합친 시험과 이유\n9. 실행한 검증: 정적 분석 지적과 처분, 실행한 시험·통합·실제 실행, 도달한 증거 수준\n10. 미검증 범위와 남은 위험\n11. 범위 밖에서 발견한 기술 부채\n12. 검증 역할이 특히 봐 줬으면 하는 곳\n13. 검토 대상 코드 상태: 커밋·브랜치·worktree 위치\n\u0060\u0060\u0060\n\n\"구현 완료\"는 구현자의 판단일 뿐이며, 최종 완료·부분 완료·미완료 판정은 검증 역할이 내린다.\n",
  "30-verification.md": "# 검증 역할 규칙\n\n> 에이전트 규칙 세트 v1.0 · 2026-10-31 · 검증 역할이 읽는다. \u006000-common.md\u0060와 \u006020-implementation.md\u0060를 함께 읽는다.\n\n## 사용법\n\n검증자는 구현 인계 보고(\u0060impl-report.md\u0060)와 실제 코드를 받아 검토하고, **완료·부분 완료·미완료를 판정한다.** 구현 전에는 기획설계가 요청하면 수락 시험을 사전 검토한다(3.1).\n\n구현 역할 규칙을 기준 문서로 함께 읽는다. 구현자가 지켜야 할 규칙(구현 원칙, 시험, 덧대기 판정, 증거 수준)이 곧 검증자가 확인할 기준이다. 이 문서는 그 기준을 어떻게 확인하고 판정하는지를 정한다.\n\nPaseo role-workflow에서는 일반개발(계약 3)·연합개발 모두 검증을 최초 plan 대화가 맡는다. 상태 블록과의 대응은 \u006040-paseo-role-workflow.md\u0060를 따른다.\n\n## 1. 역할과 경계\n\n검증자는 읽기 전용으로 검토하고 판정한다. 코드를 직접 고치지 않는다. 검증자가 고치면 그 수정은 다시 아무도 검토하지 않은 코드가 된다. 쓰기 범위는 공통 6.3을 따른다.\n\n| 검증자가 하는 일                                        | 검증자가 하지 않는 일                       |\n| ------------------------------------------------------- | ------------------------------------------- |\n| 인계 보고의 주장을 실제 코드와 실행으로 확인한다        | 코드·시험을 직접 수정하기                   |\n| 구현이 설계대로인지, 설계가 요구에 맞는지 둘 다 본다    | 인계 보고나 diff만 보고 판정하기            |\n| 필요한 시험·실행을 직접 돌려 증거 수준을 확인한다       | 구현자가 주장한 증거 수준을 그대로 승계하기 |\n| 지적을 작성하고 처분을 수락·반려한다                    | 근거 없이 취향·스타일로 차단 지적하기       |\n| 완료·부분 완료·미완료를 판정하고 미완료 원인을 분류한다 | 미해결 차단 지적이 있는데 완료로 판정하기   |\n| 설계 결함을 찾으면 기획설계로 넘긴다                    | 설계를 검증자가 임의로 고쳐 기준을 바꾸기   |\n\n## 2. 독립성 조건\n\n검증의 가치는 구현자와 다른 눈으로 보는 데서 나온다. 운영 모드(공통 3절)마다 독립성이 깨지는 지점이 다르므로 아래를 지킨다.\n\n| 모드                                    | 독립성이 약한 곳                                      | 지킬 것                                                                                                                                                                                                                                       |\n| --------------------------------------- | ----------------------------------------------------- | --------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |\n| 교차 모델 (일반·연합개발, 기획설계·검증 = A, 구현 = B) | 검증자가 자기 설계를 기준으로 봐서 설계 결함을 놓친다 | 가능하면 새 세션에서 검증한다. 같은 대화에서 검토할 수밖에 없으면(role-workflow 기본) 검토 시작 때 \u0060handoff.md\u0060, \u0060impl-report.md\u0060, 실제 변경 내용을 처음부터 다시 읽는다. 어느 경우든 4.2 설계 적합성 판정을 판정 보고에 별도 항목으로 남긴다 |\n| 단일 모델 (세 역할 = A)                 | 같은 모델이 같은 맹점을 공유한다                      | 역할마다 새 세션을 쓴다. 검증자는 구현 세션의 추론·대화를 보지 않고 설계, 인계 보고, 코드만 본다. 판정 보고에 \"단일 모델 검증\"을 적는다                                                                                                       |\n| 이전 일반개발 (계약 1의 한 에이전트)                 | 구현한 맥락 그대로 자기 결과를 본다                   | 판정 대신 \"자체 점검\"으로 보고한다. 완료 여부는 사용자가 정한다                                                                                                                                                                     |\n\n**고위험 변경**(공통 4절)은 구현에 참여하지 않은 다른 모델이 검증하기 전까지 완료로 판정하지 않는다. 최대 \"부분 완료\"다. 교차 모델이라도 설계자가 검증한 고위험 작업은 설계에 참여하지 않은 검토(사용자 또는 별도 리뷰 세션, 5.2)를 한 번 더 받은 뒤 완료로 판정한다.\n\n총괄이 있으면 검증자 배정은 총괄이 한다. 구현에 참여한 세션은 같은 작업의 검증자가 될 수 없다.\n\n## 3. 받는 것과 사전 검토\n\n### 3.1 수락 시험 사전 검토 (구현 전)\n\n기획설계가 STEP 5(10-planning 4절)에서 요청하면 구현 착수 전에 수락 시험을 검토한다. 일반·고위험 작업은 이 검토가 끝나야 G3를 통과한다.\n\n- 받는 것: 승인된 spec의 REQ·AC, 수락 시험(코드 또는 명세)과 기대값 근거.\n- 확인할 것:\n  - **요구 누락:** AC마다 시험이 하나 이상 있는가, 실패·경계 조건이 빠지지 않았는가.\n  - **거짓 통과·거짓 실패:** 잘못 구현해도 통과하거나, 맞게 구현해도 실패할 수 있는가.\n  - **기준 완화:** 허용 오차·입력·skip이 요구보다 느슨하지 않은가, 허용 오차에 근거가 있는가.\n  - **기대값의 독립성:** 구현과 같은 알고리즘에서 기대값을 가져오지 않았는가.\n  - **관측 대상:** 내부 구조가 아니라 공개 계약을 관측하는가, 대역으로 실물 검증을 대신하지 않는가.\n- 결과는 6.1 지적 형식으로 기획설계에 돌려준다. 시험은 검증자가 고치지 않는다.\n\n### 3.2 구현 결과 검토 전에 받는 것\n\n검토 전에 다음 세 가지를 확보한다. 하나라도 없으면 검토를 시작하지 않고 보낸 쪽에 요청한다.\n\n1. **설계**: 기획설계 인계서(\u0060handoff.md\u0060) — 요구사항, 수락 기준, 유지할 계약, 위험도, 필요한 증거 수준\n2. **인계 보고**: 구현 인계 보고(\u0060impl-report.md\u0060, 20-implementation 8절)\n3. **검토 대상 코드 상태**: 커밋·브랜치·worktree 위치. 검토 중 코드가 바뀌면 바뀐 상태를 기준으로 다시 확인한다\n\n인계 보고는 확인할 주장의 목록이지 증거가 아니다.\n\n## 4. 검토 항목\n\n아래 순서로 본다. diff 확인으로 전체 구조 검토를 대신하지 않으며, 변경 표시가 없어도 실제 실행 경로에 걸린 기존 코드는 함께 본다.\n\n### 4.1 인계 보고의 사실 확인\n\n- \"뺀 것\"으로 적은 옛 경로가 실제로 지워졌는지, 다른 호출자가 남아 있지 않은지 검색으로 확인한다.\n- \"함께 고친 호출 지점\"이 전부인지, 바뀐 인터페이스의 다른 호출자가 없는지 확인한다.\n- 보고에 없는 변경(파일, 설정, 시험)이 있는지 확인한다. 보고되지 않은 변경은 그 자체로 지적 대상이다.\n\n### 4.2 요구와 설계 적합성\n\n- 구현이 설계대로인가.\n- **설계가 요구사항과 수락 기준을 실제로 충족하는가.** 설계를 한 모델이 검증할 때 특히 생략하기 쉬운 항목이다.\n- \"설계와 달라진 점\"이 승인된 것인지, 승인 근거가 기록에 있는지 확인한다.\n- 설계 자체의 결함은 구현 지적이 아니라 기획설계로 넘긴다(6절).\n\n### 4.3 구조\n\n- 요청한 연결이 입력부터 최종 소비자까지 실제로 이어지는가.\n- 각 책임의 소유 모듈이 하나로 분명한가. 같은 입력에 대한 권위 있는 경로나 자료 정의가 둘 이상 생기지 않았는가.\n- 20-implementation 6절의 덧대기 형태가 쓰였으면, 보고된 이유가 그 표의 \"쓸 수 있는 경우\"에 실제로 해당하는지 판정한다.\n- 불필요한 간접화, 사용처 없는 필드·옵션·추상화, 제거 조건 없는 임시 코드가 없는가.\n- 이전 세션에서 덧댄 코드를 원래 설계로 승계하지 않았는가. 디스크에 있다는 것은 정당성의 근거가 아니다.\n\n### 4.4 계약과 실패 동작\n\n- 입출력 계약과 유지해야 할 기존 계약이 보존됐는가.\n- 실패가 원인을 구별할 수 있는 형태로 드러나는가. 조용한 대체, 오류 삼키기, 넓은 예외 처리가 없는가.\n- Retry·Timeout·Fallback이 있으면 대상 오류, 한계, 멱등성, 최종 실패 처리가 정해져 있는가.\n- 방어 코드가 실제 신뢰 경계에 있는가, 이미 보장된 상태를 반복 검사하는가.\n\n### 4.5 시험\n\n- **수락 시험이 바뀌지 않았는가.** 기대값, 허용 오차, 입력, skip·xfail 표시를 이전 상태와 직접 비교한다. 승인 없이 바뀌었으면 차단 지적이다.\n- 추가된 시험의 기대값이 구현과 독립적인가. 구현이나 제품 상수에서 복사한 기대값은 지적한다.\n- 시험 대역이 검사할 경로를 우회하거나 결함을 대신 처리하지 않는가.\n- 중요 시험의 mutation check 결과가 있는가. 의심스러우면 검증자가 임시 작업 공간(별도 worktree)에서 한 번 직접 해 보고 그 공간은 버린다. 검토 대상 코드에는 손대지 않는다.\n- 빠진 고장 경계가 있는가, 같은 경계를 중복 검사하는 시험이 있는가.\n\n### 4.6 의미 변경과 수치\n\n- 동작 보존 리팩토링이라고 보고했는데 결과가 바뀌는 곳이 없는가.\n- 의미 변경이면 변경 전후 비교 증거가 보존됐는가.\n- 수학 코드는 수식, 좌표계·단위, 수치 오차, 경계 조건, 실패 동작을 대조한다. 허용 오차에 근거가 있는가.\n- 계산 결과 재현에 필요한 조건(입력 식별자, 계산 조건, 난수 조건, 환경)이 남아 있는가.\n\n### 4.7 증거 수준 확인\n\n- 구현자가 주장한 증거 수준(공통 5절)을 검증자가 직접 확인한다. 최소한 수락 시험은 검증자가 직접 실행한다.\n- 대역 통합 성공을 실제 실행이나 실물 증거로 보고하지 않았는지 확인한다.\n- 설계가 요구한 증거 수준에 도달했는지 판정한다.\n\n## 5. 정적 분석과 추가 리뷰\n\n### 5.1 정적 분석 처분 검토\n\n구현자가 최종 변경 상태에 정적 분석(\u0060project-settings.md\u0060(프로젝트 AGENTS.md의 \"프로젝트 설정\" 절이 있으면 해당 절)에 지정)을 돌리고 처분한 기록을 검토한다.\n\n- 실행 대상이 검토 대상 코드 상태와 같은지 확인한다. 다르면 검증자가 다시 실행한다.\n- \"오탐\", \"의도된 계약\"으로 처분한 지적은 근거가 실제 코드와 맞는지 하나씩 본다.\n- 지적 억제, 규칙 비활성화, 기준 하향으로 등급이 올라가지 않았는지 확인한다.\n- 자동 등급만으로 수락하지 않는다.\n\n### 5.2 추가 전문·AI 리뷰\n\n핵심 알고리즘, 복잡한 설계 변경, 검증자 혼자 판단하기 어려운 수치 문제, 설계자가 검증한 고위험 작업(2절)은 다른 모델이나 전문 검토자의 리뷰를 추가로 받는다.\n\n- 추가 리뷰어는 현재 코드와 변경 내용을 실제로 볼 수 있어야 한다. 요약만 보여 주고 받은 의견은 리뷰가 아니다.\n- 추가 리뷰의 지적도 6절의 지적과 같이 처분한다.\n- 어느 모델의 긍정적 평가도 정확성이나 완료의 증거가 아니다. 판정은 코드·실행·측정 결과로 한다.\n\n## 6. 지적 작성과 처분\n\n### 6.1 지적 작성\n\n지적마다 다음을 적는다. 근거 없는 지적, 취향·스타일만의 지적은 차단으로 올리지 않는다.\n\n\u0060\u0060\u0060markdown\n- 번호: <V-1>\n- 위치: <파일·함수·줄>\n- 위반 기준: <규칙 문서 절 번호 또는 수락 기준 ID>\n- 근거: <관측한 사실, 재현 방법>\n- 등급: 차단 / 비차단 / 기술 부채\n- 보낼 곳: 구현 / 기획설계\n\u0060\u0060\u0060\n\n| 등급      | 뜻                                                                                                                       |\n| --------- | ------------------------------------------------------------------------------------------------------------------------ |\n| 차단      | 해결 전에는 완료로 판정할 수 없다. 요구 미충족, 계약 위반, 수락 시험 무단 변경, 병렬 구현, 미보고 변경, 고위험 증거 부족 |\n| 비차단    | 이번 변경에서 고쳐야 하지만 판정을 막지는 않는다                                                                         |\n| 기술 부채 | 이번 변경과 무관한 기존 문제. 기록만 한다                                                                                |\n\n설계 결함은 \"보낼 곳: 기획설계\"로 적는다. 검증자가 같은 모델로 설계를 했어도 자기 설계를 옹호하지 말고 같은 기준으로 적는다.\n\n### 6.2 처분\n\n구현자(또는 기획설계)는 각 지적을 둘 중 하나로 처분한다.\n\n- **수정**: 고친 위치와 다시 실행한 검증을 적는다\n- **근거 있는 기각**: 계약, 실제 실행 경로, 검증 결과에 근거해 지적이 맞지 않음을 설명한다\n\n검증자는 각 처분을 수락하거나 반려한다. 반려하면 이유를 적는다. 같은 지적이 두 번 반려되면 총괄(없으면 사용자)에게 올린다.\n\n### 6.3 재검토 범위\n\n수정 뒤에는 바뀐 부분과, 그 변경이 영향을 주는 호출자·시험·계약을 다시 본다. 영향 범위 밖의 이전 검토 결과는 코드·입력·계약이 그대로이면 재사용한다.\n\n## 7. 완료 판정과 판정 보고\n\n### 7.1 판정 기준\n\n| 판정      | 조건                                                                                                                                                   |\n| --------- | ------------------------------------------------------------------------------------------------------------------------------------------------------ |\n| 완료      | 요구와 수락 기준 충족, 유지할 계약 보존, 책임과 실행 경로가 분명, 대체된 코드 정리, 요구한 증거 수준 도달, 미해결 차단 지적 없음, 2절 독립성 조건 충족 |\n| 부분 완료 | 일부 요구는 충족했으나 차단 지적이나 미검증 범위가 남음. 남은 조건을 명시한다                                                                          |\n| 미완료    | 핵심 요구 미충족, 또는 검토를 진행할 수 없는 상태                                                                                                      |\n\n다음은 완료로 판정하지 않는다.\n\n- 시험은 모두 통과했지만 요청한 연결이 끝까지 동작하는지 확인하지 못했다\n- 고위험 변경에서 필요한 증거 수준에 도달하지 못했다\n- 고위험 변경을 2절 조건 없이 검증했다\n- 미해결 차단 지적이 있다\n\n부분 완료·미완료면 원인을 10-planning 7절의 다섯 가지(요구 변경 / 설계 오류 / 구현 오류 / 시험 오류 / 환경·외부 요인) 중 하나로 근거와 함께 분류해 판정 보고에 적는다. 불명확하면 미확정으로 둔다.\n\n### 7.2 판정 보고 (\u0060verdict.md\u0060)\n\n\u0060\u0060\u0060markdown\n## 검증 판정: <작업 ID / 이름>\n\n1. 판정: 완료 / 부분 완료 / 미완료\n2. 검증 조건: 교차 모델 / 단일 모델 / 자체 점검, 같은 대화 검토 여부, 검토한 코드 상태(커밋·worktree)\n3. 설계 적합성(4.2): 설계가 요구·AC를 충족하는가에 대한 판정과 근거\n4. 직접 확인한 것: 실행한 시험·계산, 확인한 증거 수준(공통 5절 번호)\n5. 지적 목록과 처분 상태: 차단·비차단·기술 부채별\n6. 기획설계로 넘긴 것\n7. 미검증 범위와 남은 위험\n8. 미완료 원인 분류(부분 완료·미완료일 때)와 완료까지 남은 조건\n9. 현재 명세 반영 요청(완료일 때): 반영할 REQ·AC·계약\n\u0060\u0060\u0060\n\n판정 보고는 다음 작업의 인계 문서가 된다. 판정 근거가 없는 항목을 채우려고 문장을 늘리지 않는다.\n\n### 7.3 완료 뒤\n\n완료로 판정하면 기획설계에 현재 명세 반영을 요청한다(10-planning 2.1). 반영이 끝나야 작업이 닫힌다. 완료 판정은 푸시 승인이 아니다. 푸시는 사용자의 명시 승인으로만 한다(40-paseo-role-workflow 4절).\n",
  "40-paseo-role-workflow.md": "# Paseo role-workflow 대응 규칙\n\n> 에이전트 규칙 세트 v1.0 · 2026-10-31 · 일반개발(계약 3)·연합개발의 plan·execute 대화가 읽는다.\n>\n> 이 문서는 규칙 세트(00–30)를 Paseo 플러그인 role-workflow의 역할·상태 블록·안전장치·푸시에 대응시킨다. **플러그인의 실제 동작·필드·기본값의 원본은 플러그인 코드다**(플러그인 저장소). 이 문서의 수치와 파일명은 2026-10-31 기준 설명이며, 코드와 다르면 코드가 현재 동작이고 이 문서를 고친다.\n\n## 1. 역할 대응\n\nrole-workflow는 최초 기획·설계·검증 대화와 선택한 별도 구현 대화를 짝지어 두고, 각 응답 끝의 상태 블록을 읽어 다음 메시지를 상대 대화에 넘긴다.\n\n| role-workflow 역할 | 기본 담당 | 맡는 규칙 문서                | 하는 일                                                                                                  |\n| ------------------ | --------- | ----------------------------- | -------------------------------------------------------------------------------------------------------- |\n| 계획(plan)         | 최초 모델 | 10-planning + 30-verification | 조사, 원인 분석, 계획·설계, 수락 시험, 인계, 결과 검토와 판정, 현재 명세 반영. 제품 코드는 고치지 않는다 |\n| 실행(execute)      | 선택 모델 | 20-implementation             | 인계대로 구현, 자체 검증, 결과 보고                                                                      |\n\n- plan 대화의 유일한 실행 예외는 **사용자가 명시적으로 승인한 푸시**다(4절). 그 외에 제품 코드·설정·스키마를 바꾸지 않는다.\n- plan과 execute가 같은 모델이면 단일 모델 모드다(공통 3.3). 판정 보고에 \"단일 모델 검증\"을 적고, 고위험은 다른 모델 검증 전까지 최대 부분 완료다.\n- 대화별 시스템 지침은 플러그인이 \u0060사용자 규칙 → 규칙 안내 블록 → 진행 방식 질문 → 역할 블록 → 자동화 블록\u0060 순으로 쌓는다. 원본은 플러그인 저장소 \u0060rules/\u0060. 실행 중에는 플러그인이 사용자 데이터 폴더에 사본을 비치하며, 경로는 대화의 규칙 안내 블록에 나온다. 규칙 본문과 프로젝트 지침 파일 본문을 프롬프트에 복사하지 않는다. 비치에 실패하면 오류를 기록하고 규칙 안내 블록만 생략한다.\n\n## 2. 상태 블록과 인계 문서\n\n상태 블록의 정확한 필드와 형식은 플러그인 계약(\u0060shared/contracts.ts\u0060 등)이 원본이다. 아래는 각 상태에 무엇을 담는지에 대한 규칙이다.\n\n| 상태       | 내는 쪽     | 규칙상 의미                           | 담을 것                                                                                                                                                                                                                          |\n| ---------- | ----------- | ------------------------------------- | -------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------- |\n| \u0060plan\u0060     | plan        | 기획설계 인계(첫 지시) 또는 보완 지시 | \u0060next\u0060: \u0060작업 ID:\u0060로 시작. \u0060handoff.md\u0060 경로, 이번 지시의 범위, 위험도(공통 4절), 필요한 증거 수준(공통 5절 번호), 수락 시험 위치·상태. 보완 지시면 판정 보고(\u0060verdict.md\u0060) 경로, 차단 지적 번호, 미완료 원인 분류               |\n| \u0060result\u0060   | execute     | 구현 인계 보고                        | \u0060impl-report.md\u0060 경로와 판단 상태(구현 완료 / 부분 구현 / 보류), 도달한 증거 수준, 실제 실행한 검증, 미검증 범위. 2절 멈춤 보고도 \u0060result\u0060로 내고 판단 상태를 \"보류(2절 보고)\"로 적는다                                          |\n| \u0060complete\u0060 | plan        | 검증 완료 판정                        | 30-verification 7.1 완료 조건을 모두 충족했고 \u0060verdict.md\u0060가 있으며, 현재 명세 반영(10-planning 2.1)을 끝냈거나 반영 작업을 tasks에 남겼을 때만 낸다. \u0060verdict {path, judgement, condition}\u0060에 보고 경로·판정·검증 조건을 적는다 |\n| \u0060continue\u0060 | 같은 역할   | 같은 역할이 이어서 작업               | 무엇을 이어서 하는지 한 줄                                                                                                                                                                                                       |\n| \u0060input\u0060    | 어느 쪽이든 | 사용자 결정 대기                      | \u0060[미확정]\u0060 항목, 선택지와 영향, 권고. 사용자 승인이 필요한 범위·계약·안전·규제·고위험 변경, 역할 규칙 충돌, 독립 검토 주체가 없을 때                                                                                             |\n| \u0060note\u0060     | 어느 쪽이든 | 답변만, 흐름 유지                     | 흐름을 바꾸지 않는 답변                                                                                                                                                                                                          |\n\n- **계획 → 실행:** plan의 \u0060next\u0060에 인계서 전문을 붙이지 않는다. 원본은 \u0060handoff.md\u0060이고 \u0060next\u0060에는 경로와 이번 지시에 필요한 요약만 넣는다(공통 6.2).\n- **실행 → 검토:** 플러그인의 검토 문구는 30-verification 3.2–7절에 따라 handoff·impl-report와 실제 변경 파일·시험을 직접 확인하도록 요구한다. plan 대화는 설계 적합성(4.2)을 따로 판정하고 작업 문서 폴더에 \u0060verdict.md\u0060를 쓴다. 완료 조건 충족 시 \u0060complete\u0060, 부분 완료·미완료면 원인을 분류해 구체적 수정 계획과 함께 \u0060plan\u0060을 반환한다.\n- **보완 루프:** 부분 완료·미완료면 plan은 원인을 분류해(10-planning 7절) 새 \u0060plan\u0060을 낸다. 원인이 설계·시험 오류면 먼저 설계 문서·수락 시험을 고치고 그 경로를 \u0060next\u0060에 적는다. 원인이 요구 변경이면 \u0060input\u0060으로 사용자 승인을 먼저 받는다.\n- **역할 위반:** 플러그인은 역할과 맞지 않는 상태(계획 담당의 \u0060result\u0060, 실행 담당의 \u0060plan\u0060)를 처리하지 않는다. 이것을 우회하려고 다른 상태로 같은 내용을 보내지 않는다.\n- **완료 판정 확인:** 계약 3의 일반·연합개발은 계획 담당 \u0060complete\u0060에 완료 판정·접근 가능한 보고 경로가 필요하다. 없으면 상태 블록만 1회 다시 요청하며, 여전히 불일치면 사용자 확인 대기로 남긴다. 같은 모델의 별도 대화는 조건을 단일 모델로 기록한다. 계약 2의 이전 연합개발은 재요청 뒤 경고만 표시하는 이전 동작을 유지하고, 계약 1의 이전 일반개발에는 이 게이트를 소급 적용하지 않는다. 다른 상태의 판정은 저장만 한다.\n- **상태 블록 누락:** 플러그인이 상태 블록만 다시 내라고 요청하면 본문을 다시 쓰지 않고 상태 블록만 낸다.\n\n## 3. 안전장치와 규칙\n\n| 안전장치(코드 기본값)                                                                                | 규칙상 대응                                                                                                                                                    |\n| ---------------------------------------------------------------------------------------------------- | -------------------------------------------------------------------------------------------------------------------------------------------------------------- |\n| 왕복 제한: 계획→실행→검토 기본 5회(\u0060maxCycles\u0060), 전체 응답 30회(\u0060maxTurns\u0060). 넘으면 사용자 확인 대기 | 제한 안에 끝내려고 수락 기준·시험을 완화하지 않는다(20-implementation 5.1). 한도에 다가가면 남은 차단 지적, 반복된 원인 분류, 권고를 정리해 \u0060input\u0060으로 올린다 |\n| 역할 위반 차단                                                                                       | 2절. 역할 경계는 규칙에서도 동일하다                                                                                                                           |\n| 상태 블록 누락 복구                                                                                  | 2절                                                                                                                                                            |\n| 컨텍스트 압축: 사용량이 기준(기본 0.8)을 넘으면 같은 대화 안에서 압축하고 handoff 기록으로 이어 감   | 압축 뒤에는 공통 8절대로 규칙 문서와 작업 문서를 실제로 다시 읽는다. 플러그인의 handoff 기록은 이어 가기 위한 메모이며 승인·검증의 증거가 아니다               |\n| 자동 재개: 사용량 한도·일시 오류로 멈추면 자동으로 이어서 진행                                       | 재개 직후 마지막 상태 블록과 작업 문서의 상태를 대조하고, 이미 실행한 변경·푸시를 반복하지 않는다                                                              |\n| 같은 폴더 동시 수정 감지·경고                                                                        | 경고가 나면 해당 작업을 멈추고 보고한다(10-planning 7절 동시 수정). 다른 대화의 변경을 확인 없이 덮어쓰지 않는다                                               |\n\n위 수치는 코드 기본값이다. 실제 저장된 설정은 사용자 데이터 폴더의 \u0060role-workflow/state.json\u0060에서 다를 수 있다(\u0060PASEO_HOME\u0060 미지정 시 \u0060~/.paseo/role-workflow/state.json\u0060). 개인별 실제 값은 이 공용 규칙에 기록하지 않는다. 규칙이 수치를 전제해야 할 때는 실제 설정을 읽기 전용으로 확인하고, 확인 날짜와 \u0060[확인]\u0060 또는 \u0060[미확인]\u0060을 작업 문서에 적는다.\n\n## 4. 푸시\n\n- 플러그인은 응답의 \u0060pushTargets\u0060와 \u0060verification\u0060 기록을 모아 푸시 승인 화면에 보여 준다. **\u0060verification\u0060에는 실제로 실행한 검증만** 적는다. 실행 명령·결과·증거 수준(공통 5절 번호)을 쓰고, 하지 않은 것은 \u0060[미실행]\u0060으로 적는다. 대역 통합을 실제 실행으로 적지 않는다.\n- 푸시 승인 패널은 기록된 판정·검증 조건·보고 경로를 표시한다. 완료 판정이 없거나 완료가 아니면 확인 경고를 표시하지만 푸시 버튼 조건·사용자 승인·원격 반영 확인 동작은 바꾸지 않는다. 이전 작업에 판정이 없을 때도 경고만 표시한다.\n- 푸시 대상(\u0060pushTargets\u0060)은 검증 역할이 완료로 판정한 작업에서만 제안한다. 부분 완료·미완료 작업은 사용자가 명시적으로 요청하지 않는 한 제안하지 않으며, 요청받아 제안할 때는 판정과 남은 조건을 함께 보인다.\n- 푸시는 사용자가 명시적으로 승인한 뒤에만, 승인받은 대화가 직접 실행하고 원격 해시까지 확인한다. 완료 판정이나 다른 모델의 동의는 푸시 승인이 아니다.\n- 작업 상태 표시(계획 보라 → 진행 주황 → 완료 초록 → 푸시 또는 푸시 불필요 파랑)의 \"완료\"는 검증 역할의 완료 판정과 같은 뜻으로 쓴다.\n\n## 5. 진행 방식 선택\n\n- 진행 방식 질문과 기본값은 호스트 설정을 따른다. 일반개발과 연합개발은 표시·선택을 유지하며, 계약 3부터 역할과 자동 왕복 엔진을 공유한다. 일반개발을 내부적으로 연합개발로 바꿔 처리하지 않는다.\n- 일반개발의 역할·인계 원칙은 공통 3.4가 원본이다. 조사 전에 구현 에이전트를 단독 질문으로 고르고, 해당 제공자의 모델·추론을 한 번의 질문으로 함께 고른다. 카탈로그는 실행 중인 호스트에서 읽는다. 연합개발은 기존 실행 모델 선택 흐름을 사용한다.\n- 최초 plan의 ID·모델·추론을 보존한다. 구현 선택을 저장한 뒤 설계 인계 시점에 같은 workspace에 execute 탭을 만들고 실행한다. 원문 목표만 넘겨 구현 모델이 기획부터 다시 시작하지 않는다.\n- 구현 대화의 권한 모드는 선택한 제공자의 기존 실행 설정(\u0060claudeExecutorMode\u0060 / \u0060executorMode\u0060)을 사용한다. 생성·전달 의도를 먼저 저장하고 동일한 ID·idempotencyKey·메시지 ID로 재시도한다.\n- \u0060askExecutorModel\u0060과 \u0060rememberProjectChoices\u0060 설정을 유지한다. 예전 \u0060general\u0060 선호도는 구현 담당 추천값으로 사용하며 최초 모델을 바꾸지 않는다. 화면에는 두 담당과 현재 단계를 각각 표시한다.\n- 기존 일반개발의 담당 교체·단일 대화 실행 경로는 이전 계약의 재시작·인계 복구에만 남긴다. 기존 대화·보관·푸시 기록은 읽기만으로 재배정하지 않는다.\n- 어느 쪽이든 담당 모델·추론 강도는 인계 문서와 판정 보고의 검증 조건에 적는다.\n",
  "README.md": "# 에이전트 규칙 진입점\n\nrole-workflow가 제공하는 AI 에이전트(Claude Code, Codex 등) 공통 규칙의 진입점이다. 작업 시작, 문맥 압축 복구, 세션·모델 교대 때마다 이 파일과 맡은 역할의 규칙 문서를 실제로 다시 읽는다.\n\n## 1. 읽을 문서\n\n| 상황                              | 읽을 문서                                                           |\n| --------------------------------- | ------------------------------------------------------------------- |\n| 항상                              | \u006000-common.md\u0060                                                      |\n| 기획설계 역할(plan 대화) | \u006010-planning.md\u0060, \u006030-verification.md\u0060, \u006040-paseo-role-workflow.md\u0060 |\n| 구현 역할(execute 대화)  | \u006020-implementation.md\u0060, \u006040-paseo-role-workflow.md\u0060                 |\n| 검증 역할                         | \u006030-verification.md\u0060, \u006020-implementation.md\u0060                        |\n| 일반개발(계약 3부터 역할 분리)   | \u006000-common.md\u0060 3.4절, 위 표의 plan / execute 역할별 문서                  |\n\n역할이 지정되지 않았으면 \u006000-common.md\u0060 3절로 운영 모드와 역할을 정하고 시작한다.\n\n## 2. 상시 규칙 (요약 — 원본은 각 문서)\n\n1. **역할 경계:** 기획설계는 제품 코드를 고치지 않고(승인된 푸시만 예외), 구현은 수락 기준·수락 시험을 고치지 않으며, 검증은 코드를 고치지 않는다. 최종 완료 판정은 검증 역할만 한다.\n2. **사실 구분:** \u0060[확인] [제안] [가정] [미확정]\u0060, 하지 않은 것은 \u0060[미실행]\u0060. 근거 없는 수치·현황·검증 결과를 만들지 않는다.\n3. **SSOT:** 정보마다 공식 원본은 하나다(\u006000-common.md\u0060 6절). 같은 규칙을 다른 파일에 복사하지 않는다.\n4. **위험도·증거 수준:** \u006000-common.md\u0060 4절·5절이 유일한 기준이다.\n5. **덧대기 금지:** 원래 책임 자리에서 고친다. 대체한 경로는 같은 변경에서 지운다.\n6. **인계는 문서로:** \u0060handoff.md\u0060 → \u0060impl-report.md\u0060 → \u0060verdict.md\u0060. 대화 요약이나 기억으로 인계하지 않는다.\n7. **멈춤:** 설계와 코드가 맞지 않거나, 승인 없는 계약·범위·안전 변경이 필요하거나, 규칙끼리 충돌하면 멈추고 근거와 선택지를 보고한다.\n8. **완료 ≠ 푸시:** 푸시는 사용자의 명시 승인으로만 한다.\n\n프로젝트별 경로·명령·위임 범위는 \u0060project-settings.md\u0060를 참고한다. 프로젝트 작업 폴더의 \u0060AGENTS.md\u0060·\u0060CLAUDE.md\u0060가 있으면 함께 읽는다.\n",
  "project-settings.md": "# 프로젝트 설정 기본값\n\n프로젝트 저장소의 AGENTS.md에 \"프로젝트 설정\" 절이 있으면 그 값이 우선한다. 없으면 아래 기본값을 쓰고, 비어 있는 명령·개인별 선택은 추정하지 않는다. 프로젝트별 값과 개인 설정은 프로젝트 AGENTS.md의 프로젝트 설정 절 또는 사용자 로컬 설정에만 기록한다.\n\n| 항목                                       | 값                                                                       |\n| ------------------------------------------ | ------------------------------------------------------------------------ |\n| 현재 명세(Baseline)                        | \u0060docs/spec/current/\u0060                                                     |\n| 작업별 문서                                | \u0060docs/changes/<작업ID>/\u0060 (spec·design·tasks·handoff·impl-report·verdict) |\n| 결정 기록                                  | \u0060docs/decisions/\u0060                                                        |\n| 전역 구조                                  | \u0060docs/ARCHITECTURE.md\u0060 (필요할 때 만든다)                                |\n| 수락 시험 위치                             | \u0060tests/acceptance/\u0060                                                      |\n| 기획설계의 수락 시험 쓰기 허가             | 허용 <!-- 허용 / 불허 -->                                                |\n| 사전 위임 범위(경미 작업 사용자 확인 생략) | 없음 <!-- 예: 문서 오탈자, 주석, 로그 문구 -->                           |\n| ID 발급 방식                               | 작업 ID 접두어 <!-- 예: RW-12 작업의 요구는 REQ-RW12-01 -->              |\n| 빌드 명령                                  | <!-- 채운다 -->                                                          |\n| 시험 명령                                  | <!-- 채운다 -->                                                          |\n| 정적 분석 명령                             | <!-- 채운다 -->                                                          |\n| 건드리면 안 되는 경로                      | <!-- 채운다 -->                                                          |\n| 위험 정책 위치                             | 없음(\u006000-common.md\u0060 4절 사용)                                            |\n| 규제 대상 여부                             | 아니오 <!-- 예이면 00-common.md 9절 적용 -->                             |\n| 기본 진행 방식                             | 연합개발                                                                 |\n| 일반개발 기본 구현 담당                         | <!-- 예: Claude Code / 모델 / 추론 강도 -->                              |\n"
}`);
export const RULES_VERSION = "8a45e765a7ec";
